const cat={q:'',course:store.get('catCourse',''),sem:'',ctrl:'',diff:'',n:12};
const CTRLS=['Экзамен','Зачёт','Письменно','Тест','Устно','Кейс'];
function catFilter(){const q=norm(cat.q.trim());return SUBJECTS.filter(s=>(!q||norm(s.name+' '+(s.alias||'')+' '+(has('teachers')?teachers(s).map(t=>t.name).join(' '):'')).includes(q))&&(!cat.course||(cat.course==='fav'?S.fav.includes(s.id):s.courses.includes(+cat.course)))&&(!cat.sem||s.sems.includes(+cat.sem))&&(!cat.ctrl||(s.full&&(s.control===cat.ctrl||s.formats.includes(cat.ctrl))))&&(!cat.diff||String((diffOf(s)||{lv:0}).lv)===cat.diff)).sort((a,b)=>(b.full-a.full)||(a.courses[0]-b.courses[0])||a.name.localeCompare(b.name,'ru'))}
function catDraw(){const a=catFilter(),box=$('#rows');if(!box)return;$('#cnt').textContent=`Найдено: ${a.length}`;$('#reset').hidden=!(cat.q||cat.course||cat.sem||cat.ctrl||cat.diff);
 box.innerHTML=a.length?`<div class="deck">${a.slice(0,cat.n).map(gcard).join('')}</div>`:latEmpty(cat.course==='fav'&&!S.fav.length?'Здесь будут твои предметы':'Такого предмета нет',cat.course==='fav'&&!S.fav.length?`Открой предмет и нажми «В мои предметы», и он появится здесь.`:`${HELP} проверила весь список. Попробуй другое название или сбрось фильтры.`,cat.course==='fav'?'lat_peek':'lat_sad');
 const m=$('#more');m.hidden=a.length<=cat.n;m.textContent=`Показать ещё ${Math.min(12,a.length-cat.n)}`;$$('.seg button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.c===cat.course))}
