R.teachers=()=>({title:`Преподаватели ${D.uni}`,after:fcDraw,html:`<div class="wrap"><div class="phead ph-row"><div><h1 tabindex="-1">Преподаватели</h1><p class="d">Распределены по курсам. Сведения взяты с официальной страницы школы. Тег «Уважаемый» даём отдельно, за особые заслуги: доброту, понимание и помощь студентам.</p></div><div class="m-hide">${mainCta()}</div></div>${has('teachers')?`<div class="filters f3"><div class="wide"><label class="fl" for="q">Поиск</label><input id="q" type="search" value="${esc(fc.q)}" placeholder="Фамилия или дисциплина"></div><div class="wide"><span class="fl" id="ltc">Курс</span><div class="seg" role="group" aria-labelledby="ltc">${[['','Все'],['1','1'],['2','2'],['3','3'],['4','4']].map(c=>`<button type="button" data-tc="${c[0]}" aria-pressed="false">${c[1]}</button>`).join('')}</div></div><div class="wide"><label class="fl" for="fd">Кафедра</label><select class="f" id="fd"><option value="">Все</option>${Object.entries(DEPTS).map(x=>`<option value="${x[0]}" ${x[0]===fc.d?'selected':''}>${x[1]}</option>`).join('')}</select></div></div><div class="res"><b id="cnt" aria-live="polite"></b><button type="button" class="link" id="reset" hidden>Сбросить фильтры</button></div><div id="frows"></div><div style="text-align:center;margin-top:20px"><button type="button" class="btn btn-oo" id="more" hidden></button></div><p class="small muted" style="margin-top:14px">Источник: <a href="${D.teachersUrl}" target="_blank" rel="noopener">официальная страница школы</a>.</p>`:lockP(D.access.teachers,'Сведения о преподавателях')}<section class="sec"><div class="sec-head"><h2 class="sec-t">Редкая коллекция котов</h2></div><div class="deck tdeck">${CAT_CARDS.map(catCard).join('')}</div></section><div class="d-hide" style="margin-top:18px">${mainCta()}</div></div>`});
function openTeacher(id){const t=T(id);lastF=document.activeElement;closeOv();const ov=document.createElement('div');ov.className='overlay';ov.id='ov';const subs=t.subs.map(byId).filter(Boolean);ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dlgT"><button class="ib x" id="ovX" aria-label="Закрыть">${I.x}</button>${t.photo?`<img loading="lazy" decoding="async" class="t-ph" src="${t.photo}" alt="">`:''}<h2 id="dlgT">${esc(t.name)}</h2><dl class="sumd"><div><dt>Должность и степень</dt><dd>${esc(t.role)}</dd></div><div><dt>Кафедра</dt><dd>${DEPTS[t.dept]}</dd></div><div><dt>Курсы</dt><dd>${tcLabel(t)}</dd></div></dl>${subs.length?`<h3 class="t-h">Предметы на платформе</h3><div class="t-links">${subs.map(x=>`<a class="link" href="/subject/${x.id}">${esc(x.name)}</a>`).join('')}</div>`:''}<h3 class="t-h">Дисциплины</h3>${t.disc.length?`<ul class="t-list">${t.disc.map(x=>`<li>${sLink(x)}</li>`).join('')}</ul>`:'<p class="muted">На сайте школы не указаны.</p>'}<div class="dlg-b"><a class="link" href="${D.teachersUrl}" target="_blank" rel="noopener">Официальная страница</a>${S.admin?`<button class="btn btn-oo btn-sm" data-tedit="${t.id}">Изменить</button>`:''}</div></div>`;document.body.append(ov);$('#ovX').focus()}
