function openTeacherEdit(id){const t=T(id);closeOv();tcSubs=[...t.subs];const ov=document.createElement('div');ov.className='overlay';ov.id='ov';ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dlgT"><button class="ib x" id="ovX" aria-label="Закрыть">${I.x}</button><h2 id="dlgT">Изменить преподавателя</h2><p class="muted small" style="margin:-6px 0 10px">Изменения сразу появятся на карточке, в предметах, в поиске и в фильтрах.</p><form id="tcE" data-id="${t.id}" class="tform"><label>ФИО<input type="text" name="name" value="${esc(t.name)}" maxlength="90"></label><label>Должность и степень<input type="text" name="role" value="${esc(t.role)}" maxlength="120"></label><label>Кафедра<select class="f" name="dept">${Object.entries(DEPTS).map(x=>`<option value="${x[0]}" ${x[0]===t.dept?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Дисциплины, каждая с новой строки<textarea name="disc" rows="4">${esc(t.disc.join('\n'))}</textarea></label><div class="tsw"><span class="tsl">Предметы на платформе</span><div id="tsL" class="tsL"></div><select class="f" id="tsAdd" aria-label="Добавить предмет"><option value="">Добавить предмет</option>${[...SUBJECTS].sort((a,b)=>a.name.localeCompare(b.name,'ru')).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><label>Фото, только с согласия преподавателя<input type="file" name="photo" accept="image/*"></label><p class="small" id="tcErr" style="color:#A81E1E" hidden></p><div class="dlg-b"><button type="button" class="link" id="tcReset" data-id="${t.id}" style="color:var(--ink-2)">Вернуть как на сайте школы</button><button class="btn btn-o btn-sm">Сохранить</button></div></form></div>`;document.body.append(ov);drawTcSubs();$('input',$('#tcE')).focus()}
function openDiff(sid){const s=byId(sid),d=diffOf(s)||{lv:0,score:'',note:''};lastF=document.activeElement;closeOv();const ov=document.createElement('div');ov.className='overlay';ov.id='ov';ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dlgT"><button class="ib x" id="ovX" aria-label="Закрыть">${I.x}</button><h2 id="dlgT">Сложность предмета</h2><p class="muted small" style="margin:-6px 0 10px">${esc(s.name)}</p><form id="dfF" data-sid="${s.id}" class="tform" novalidate><label>Уровень<select class="f" name="lv"><option value="0" ${!d.lv?'selected':''}>Не оценена</option>${LEVELS.map(l=>`<option value="${l.id}" ${l.id===d.lv?'selected':''}>${l.name}</option>`).join('')}</select></label><label>Баллы <input type="number" name="score" min="1" max="99" value="${d.score||''}" placeholder="Необязательно"></label><label>Комментарий о предмете<input type="text" name="note" value="${esc(d.note||'')}" maxlength="120" placeholder="Например: сложно, но интересно"></label><div class="dlg-b"><span></span><button class="btn btn-o btn-sm">Сохранить</button></div></form></div>`;document.body.append(ov);$('select',ov).focus()}
const revLabel=s=>{const n=reviewsOf(s).length;return n?`Отзывы (${n})`:'Отзывы'};
const revAvg=s=>{const r=reviewsOf(s);return r.length?(r.reduce((a,x)=>a+x.load,0)/r.length).toFixed(1).replace('.',','):''};
