const reviewsHtml=s=>{const r=[...reviewsOf(s)].reverse();return `<section class="card pad"><h2>Оставить отзыв</h2><form id="revF" data-sid="${s.id}" class="revf"><textarea name="t" rows="3" maxlength="600" aria-label="Текст отзыва" placeholder="Как проходит курс, что важно на контроле, как лучше готовиться"></textarea><div class="revr"><div><span class="fl" id="rl1">Сложность предмета</span><div class="pills" role="radiogroup" aria-labelledby="rl1">${[1,2,3,4,5].map(n=>`<label class="pill"><input type="radio" name="load" value="${n}" ${n===3?'checked':''}><span>${n}</span></label>`).join('')}</div></div><div><span class="fl" id="rl2">Как подписать</span><div class="pills" role="radiogroup" aria-labelledby="rl2"><label class="pill"><input type="radio" name="who" value="me" checked><span>От своего имени</span></label><label class="pill"><input type="radio" name="who" value="anon"><span>Анонимно</span></label></div></div></div><p class="small muted">Пиши о предмете, без оскорблений и личных данных. Администратор может удалить отзыв.</p><p class="small" id="revE" style="color:#A81E1E" hidden></p><button class="btn btn-oo btn-sm">Опубликовать отзыв</button></form></section><section class="card pad"><div class="hh between"><h2>Отзывы о предмете</h2><span class="muted small">${revSummary(s)}</span></div>${r.length?r.map(x=>`<article class="rv"><header><span class="ava-i">${x.anon?'?':esc((x.name||'@').replace('@','')[0]||'С').toUpperCase()}</span><div><b>${x.anon?'Анонимно':esc(x.name)}</b><small>${fmtD(x.at)}, сложность ${x.load} из 5</small></div>${x.ex?EX:''}${x.mine||S.admin?`<button class="ib" data-rdel="${x.id}" data-sid="${s.id}" aria-label="Удалить отзыв">${I.x}</button>`:''}</header><p>${esc(x.t)}</p></article>`).join(''):latEmpty('Отзывов пока нет','Напиши первым: так другим будет проще подготовиться.','lat_wave').replace('card empty','empty')}</section>`};
const notesHtml=s=>`<section class="card pad"><div class="hh between"><div class="hh" style="margin:0"><h2>Конспекты</h2>${EX}</div><button class="btn btn-oo btn-sm" data-prop="${s.id}" data-i="new" data-type="missing">Добавить тему</button></div>${topicsOf(s).map((x,i)=>{const e=edits(s,i),last=e[e.length-1],added=x[2];return `<details class="doc" ${i?'':'open'}><summary>${esc(x[0])}</summary><p>${esc(noteText(s,i))}</p><div class="doc-f"><span class="small muted">${last?`Правок: ${e.length}, последняя: ${esc(last.by)}, ${fmtD(last.at)}`:added?`Тему добавил: ${esc(added)}`:'Правок пока нет'}</span><button class="link" data-prop="${s.id}" data-i="${i}" data-type="fix">Предложить правку</button></div></details>`}).join('')}<p class="small muted" style="margin-top:8px">Принятые правки приносят рубли на счёт. <a href="/contrib">Как это работает</a></p></section>`;
