 const locks={notes:'Конспекты',tests:'Контрольные',exams:'Работы зачётов и экзаменов',course:'Поэтапные курсы',trainer:'Тренажёры',proj:'Списки проектов',teach:'Сведения о преподавателях'};
 if(t==='over'&&!s.full)return latEmpty('Карточку ещё собираем','Темы и материалы появятся после сверки с программой курса.')+earnCard(s);
