R.contrib=()=>{const title=`Мой вклад: правки конспектов и внутренние рубли`;const mine=S.props.filter(p=>p.by===ME).slice().reverse(),log=S.wallet.log.slice().reverse();
 return{title,html:`<div class="wrap"><div class="phead ph-row"><div><h1 tabindex="-1">Мой вклад</h1><p class="d">Каждая принятая правка приносит внутренние рубли: на подписку или в подарок другому.</p></div><a class="btn btn-o cta1" href="/subjects" data-goal="contrib_find">Найти конспект для правки</a></div><div class="g2"><section class="card pad bal">${spr('ste_coin',SN,'bal-cat')}<div><span class="muted">На счёте</span><div class="bal-n">${rub(S.wallet.bal)}</div><p class="small muted">${TAR} спишет их при оплате подписки. Вывести нельзя, всё внутри платформы.</p></div></section><section class="card pad"><h3 style="margin-bottom:8px">До бесплатного месяца</h3>${D.tiers.map(barTier).join('')}</section></div>
 <section class="sec"><div class="sec-head"><h2 class="sec-t">Поделиться рублями</h2></div><form class="card pad trf" id="trF" novalidate><div><label class="fl" for="trU">Кому</label><input type="text" id="trU" name="u" placeholder="@username в Telegram"></div><div><label class="fl" for="trA">Сумма</label><input type="number" id="trA" name="a" min="1" max="${S.wallet.bal}" placeholder="Например, 50"></div><div class="trc"><label class="fl" for="trC">Сообщение <span class="opt">(необязательно)</span></label><input type="text" id="trC" name="c" maxlength="80" placeholder="За помощь с проектом"></div><button class="btn btn-oo">Перевести</button><p class="small" id="trE" style="color:#A81E1E;grid-column:1/-1" hidden></p></form></section>
 <section class="sec"><div class="sec-head"><h2 class="sec-t">История счёта</h2></div><div class="card pad">${log.map(l=>`<div class="rowp"><span>${esc(l[0])}<br><small class="muted">${fmtD(l[2])}</small></span><b class="${l[1]>0?'plus':'minus'}">${l[1]>0?'+':'−'}${rub(Math.abs(l[1]))}</b></div>`).join('')}</div></section>
 <section class="sec"><div class="sec-head"><h2 class="sec-t">Мои правки</h2></div><div class="card pad">${mine.length?mine.map(p=>`<div class="prow"><div><b>${esc(byId(p.sid).name)}: ${esc(propTitle(p))}</b><span class="muted small">${TYPES[p.type]}, ${fmtD(p.at)}</span>${p.reason?`<span class="small">Причина: ${esc(p.reason)}</span>`:''}</div>${statusTag(p)}</div>`).join(''):'<p class="muted">Правок пока нет.</p>'}</div></section>
 <section class="sec"><div class="sec-head"><h2 class="sec-t">Сколько начисляем</h2></div><div class="card pad">${D.bounty.map(b=>`<div class="rowp"><span>${b[0]}</span><b>до ${rub(b[1])}</b></div>`).join('')}<p class="small muted" style="margin-top:8px">Итоговую сумму определяет администратор.</p></div></section></div>`}};
R.admin=p=>{const title=`Модерация: ${D.brand}`,tab=p&&p.tab==='fines'?'fines':'props';if(!S.admin)return{title,html:`<div class="wrap"><div class="card done">${spr('lat_grump',LN)}<h1 tabindex="-1" class="h1">Раздел для администратора</h1><p class="muted">Переключи «Доступ» в тёмной полосе на «администратор».</p><a class="btn btn-o cta1" href="/">На главную</a></div></div>`};
 const q=S.props.filter(p=>p.status==='pending'),done=S.props.filter(p=>p.status!=='pending').slice().reverse();
 return{title,html:`<div class="wrap"><div class="phead ph-row"><div><h1 tabindex="-1">Модерация</h1><p class="d">Правки и штрафы участников заполнены как ${EX}. Дубли и пустые правки отклоняй без начисления, штраф за них не назначается, доначислить можно позже. Преподавателей и сложность предметов можно менять прямо на их страницах.</p></div>${spr('lat_read',LN,'head-cat')}</div>${adminTabs(tab,q.length)}${tab==='fines'?adminFines():q.length?`<div class="stack">${q.map((p,idx)=>{const s=byId(p.sid),isNew=p.topic==='new',old=isNew?'':noteText(s,p.topic);return `<article class="card pad adm" data-prop-id="${p.id}"><div class="tags"><span class="tag soon">${TYPES[p.type]}</span><span class="tag">${esc(s.name)}</span><span class="tag">${esc(p.by)}, ${fmtD(p.at)}</span></div><h2>${esc(propTitle(p))}${isNew?' (новая тема)':''}</h2><p class="diff">${isNew?`<ins>${esc(p.text)}</ins>`:wdiff(old,p.text)}</p><p class="small"><b>Доказательство:</b> ${p.proof&&(p.proof.file||p.proof.link)?esc(p.proof.file||p.proof.link):'не приложено'}</p><div class="amts"><span class="fl">Начислить</span>${D.chips.map(v=>`<button type="button" class="tab" data-amt="${v}">${v} ₽</button>`).join('')}<input type="number" min="0" max="5000" step="10" aria-label="Сумма начисления" value="${p.type==='program'?300:p.type==='missing'?150:50}"></div><input type="text" class="reason" aria-label="Причина отказа" placeholder="Причина, если отклоняешь"><p class="small adm-e" style="color:#A81E1E" hidden></p><div class="adm-b"><button class="btn btn-oo btn-sm" data-no="${p.id}">Отклонить</button><button class="btn btn-o btn-sm ${idx?'':'cta1'}" data-ok="${p.id}">Принять и начислить</button></div></article>`}).join('')}</div>`:`<div class="card empty">${spr('lat_sleep',LN)}<h3>Очередь пуста</h3><p class="muted">${HELP} проверила всё.</p><a class="btn btn-o cta1" href="/subjects">Открыть предметы</a></div>`}${tab==='props'&&done.length?`<section class="sec"><div class="sec-head"><h2 class="sec-t">Решения</h2></div><div class="card pad">${done.map(p=>`<div class="prow"><div><b>${esc(byId(p.sid).name)}: ${esc(propTitle(p))}</b><span class="muted small">${esc(p.by)}${p.reason?`. ${esc(p.reason)}`:''}</span></div>${statusTag(p)}</div>`).join('')}</div></section>`:''}</div>`}};
const adminTabs=(tab,q)=>{const ap=S.fines.filter(f=>f.status==='appeal').length;return `<nav class="tags atabs" aria-label="Разделы модерации"><a class="tab" href="/admin" ${tab==='props'?'aria-current="page"':''}>Правки${q?` (${q})`:''}</a><a class="tab" href="/admin?tab=fines" ${tab==='fines'?'aria-current="page"':''}>Штрафы${ap?` (${ap})`:''}</a></nav>`};
const adminFines=()=>{const ap=S.fines.filter(f=>f.status==='appeal'),all=[...S.fines].reverse(),t0=D.fines.types[0];return `<div class="stack"><section class="card pad"><h2>Назначить штраф</h2><form id="fineF" class="tform" novalidate><div class="two2"><label>Кому<input type="text" name="u" placeholder="@username"></label><label>Нарушение<select class="f" name="type">${D.fines.types.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label>Сумма, ₽<input type="number" name="a" min="1" max="${t0[3]}" value="${t0[3]}"></label><label>Доказательство<input type="text" name="proof" placeholder="Скриншот или ссылка"></label></div><label>Что произошло<textarea name="note" rows="2" maxlength="300"></textarea></label><p class="small" id="fineE" style="color:#A81E1E" hidden></p><div class="dlg-b"><span></span><button class="btn btn-o btn-sm cta1">Назначить штраф</button></div></form></section>${ap.map(f=>`<article class="card pad adm" data-fine="${f.id}"><div class="tags"><span class="tag soon">Обжалование</span><span class="tag">${esc(f.user)}, ${fmtD(f.at)}</span><span class="tag">${rub(f.amount)}</span></div><h2>${esc(ftype(f.type)[1])}</h2><p>${esc(f.note)}</p><p class="small"><b>Доказательство:</b> ${esc(f.proof)}</p><p class="diff"><b>Участник пишет:</b> ${esc(f.appeal)}</p><input type="text" class="reason" aria-label="Ответ участнику" placeholder="Ответ участнику"><p class="small adm-e" style="color:#A81E1E" hidden></p><div class="adm-b"><button class="btn btn-oo btn-sm" data-fkeep="${f.id}">Оставить в силе</button><button class="btn btn-oo btn-sm" data-fdrop="${f.id}">Отменить штраф</button></div></article>`).join('')}<section class="card pad"><h2>Все штрафы</h2>${all.map(f=>`<div class="prow"><div><b>${esc(f.user)}: ${esc(ftype(f.type)[1])}</b><span class="muted small">${rub(f.amount)}, ${fmtD(f.at)}</span></div><span class="tag ${FSTAT[f.status][1]}">${FSTAT[f.status][0]}</span></div>`).join('')}</section></div>`};
function decide(id,ok,card){const p=S.props.find(x=>x.id==id),err=$('.adm-e',card);if(ok){const a=+$('input[type=number]',card).value;if(!(a>=0)){err.hidden=false;err.textContent='Укажи сумму';return}p.status='ok';p.amount=a;if(p.topic==='new'){(S.extra[p.sid]=S.extra[p.sid]||[]).push([p.title,p.text,p.by])}else{const k=p.sid+':'+p.topic;(S.edits[k]=S.edits[k]||[]).push({t:p.text,by:p.by,at:T0})}if(p.by===ME){S.wallet.bal+=a;S.wallet.log.push([`Правка: ${propTitle(p)}`,a,T0])}saveC();goal('prop_accept');toast(`Правка принята, начислено ${rub(a)}`)}else{const r=$('.reason',card).value.trim();if(!r){err.hidden=false;err.textContent='Напиши причину отказа, её увидит автор';$('.reason',card).focus();return}p.status='no';p.reason=r;saveC();toast('Правка отклонена')}rerender()}
const ME_TG='@student',FSTAT={active:['Нужно оплатить','bad'],appeal:['На рассмотрении','soon'],paid:['Оплачен','live'],cancelled:['Отменён','']};
