R.account=()=>{if(!S.auth)return R.register({});const t=tierBy(S.tier),inv=visible().filter(x=>!x.own).length,ORD={active:0,appeal:1,paid:2,cancelled:3},my=[...myFines()].sort((a,b)=>ORD[a.status]-ORD[b.status]||(a.at<b.at?1:-1)),un=unpaid(),sum=un.reduce((a,f)=>a+f.amount,0),first=un.find(f=>S.wallet.bal>=f.amount);const acc=`<div class="card reg"><dl class="sumd"><div><dt>Аккаунт</dt><dd>${ME_TG} ${EX}</dd></div><div><dt>Тариф</dt><dd>${t?`${t.name}, ${rub(t.level)} ${D.period}`:'Без подписки'}</dd></div><div><dt>На счёте</dt><dd>${rub(S.wallet.bal)}</dd></div><div><dt>Штрафы к оплате</dt><dd class="${sum?'fine-a':''}">${sum?rub(sum):'нет'}</dd></div><div><dt>Проекты по приглашению</dt><dd>${inv}</dd></div></dl><a class="btn ${first?'btn-oo':'btn-o cta1'} btn-full" href="/pricing">${t?'Сменить тариф':'Подключить тариф'}</a><a class="link" href="/contrib">Мой вклад и правки</a>${S.admin?'<a class="link" href="/admin">Модерация</a>':''}<a class="link" href="/projects">Мои проекты</a><button class="link" id="logout" style="color:var(--ink-2)">Выйти</button></div>`,fin=`<section class="sec cab-f" id="fines"><div class="sec-head"><h2 class="sec-t">Штрафы</h2>${EX}</div>${my.length?`<div class="card pad fines">${my.map(f=>fineCard(f,first&&f.id===first.id)).join('')}</div>`:`<div class="card empty">${spr('lat_heart',LN)}<h3>Штрафов нет</h3><p class="muted">Так держать.</p></div>`}<p class="small muted" style="margin-top:12px">Штрафы назначаются во внутренних рублях за нарушение <a href="/rules">правил сервиса, раздел 7</a>. Пока штраф не оплачен, рубли со счёта нельзя переводить и тратить на подписку.</p></section>`;return{title:`Кабинет: ${D.brand}`,html:`<div class="wrap narrow"><div class="phead"><h1 tabindex="-1">Кабинет</h1></div>${un.length?fin+'<div style="margin-top:24px">'+acc+'</div>':acc+fin}</div>`}};
