/* Погоны: схема, без точных размеров по приказу. Звёзды и полосы по правилам ношения знаков различия. */
const RANKS=[['Лейтенант',{pr:1,st:[[13,80],[33,80]],r:4.5}],['Старший лейтенант',{pr:1,st:[[13,80],[33,80],[23,63]],r:4.5}],['Капитан',{pr:1,st:[[13,80],[33,80],[23,63],[23,46]],r:4.5}],['Майор',{pr:2,st:[[23,80]],r:6.5}],['Подполковник',{pr:2,st:[[14,80],[32,80]],r:6.5}],['Полковник',{pr:2,st:[[14,80],[32,80],[23,58]],r:6.5}]];
const starP=(cx,cy,r)=>{let p='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.42:r;p+=(i?'L':'M')+(cx+rr*Math.cos(a)).toFixed(1)+' '+(cy+rr*Math.sin(a)).toFixed(1)}return p+'Z'};
function pogon(o){const G='#D9B44A',F=o.gen?'#C9A43A':'#556535';let b=`<path d="M2 16 L23 3 L44 16 L44 116 Q44 120 40 120 L6 120 Q2 120 2 116 Z" fill="${F}" stroke="#2B3318" stroke-width="2"/>`;
 if(o.gen)for(let y=26;y<116;y+=8)b+=`<path d="M4 ${y} l5 -4 l5 4 l5 -4 l5 4 l5 -4 l5 4 l5 -4 l5 4 l3 -2" fill="none" stroke="#A8862A" stroke-width="1.2"/>`;
 if(o.pr===1)b+=`<rect x="21" y="18" width="4" height="100" fill="#B3262B"/>`;
 if(o.pr===2)b+=`<rect x="11" y="18" width="4" height="100" fill="#B3262B"/><rect x="31" y="18" width="4" height="100" fill="#B3262B"/>`;
 for(let i=0;i<(o.lat||0);i++)b+=`<rect x="3" y="${104-i*8}" width="40" height="4" fill="${G}"/>`;
 if(o.wide)b+=`<rect x="3" y="98" width="40" height="12" fill="${G}"/>`;
 if(o.lon)b+=`<rect x="17" y="18" width="12" height="100" fill="${G}"/>`;
 (o.st||[]).forEach(s=>b+=`<path d="${starP(s[0],s[1],o.r)}" fill="${o.gen?'#7A5A10':G}" stroke="${o.gen?'#5A420A':'#8C6F1E'}" stroke-width=".8"/>`);
 if(o.emb)b+=`<circle cx="23" cy="44" r="9" fill="none" stroke="#7A5A10" stroke-width="2"/><path d="${starP(23,44,5)}" fill="#B3262B"/>`;
 b+=`<circle cx="23" cy="12" r="4.5" fill="${o.gen?'#7A5A10':G}" stroke="#2B3318"/>`;
 return `<svg viewBox="0 0 46 122" width="46" height="122" aria-hidden="true">${b}</svg>`}

/* Руководство ВУЦ: должности и фото по материалам роты. Цвет — строгость, как у предметов. */
const LEAD=[['Колышкин Виталий Геннадьевич','Начальник учебного центра','/img/l_kol.6f557c.webp',1],['Янгляев Дамир Хайдарович','Заместитель начальника учебного центра','/img/l_yan.947f06.webp',1],['Сацута Сергей Александрович','Начальник кафедры № 1 (общевойсковой подготовки)','/img/l_sac.5224b6.webp',1],['Григорец Дмитрий Владимирович','Начальник учебной части','/img/l_gri.cd16bb.webp',5]];
const leadCard=l=>{const v=l[3]===5?lvl(5):{c1:'#5B6B34',c2:'#3F4D22'};return `<article class="vk-ld ${l[3]===5?'hard':''}" style="--c:${v.c1};--cd:${v.c2}"><div class="vk-ph"><img loading="lazy" decoding="async" src="${l[2]}" alt="${l[0]}" loading="lazy"><span class="vk-lvc">${l[3]===5?'Строгий':'Уважаемый'}</span>${l[3]===5?spr('ste_strict','Степан поправляет фуражку','vk-strict'):''}</div><div class="vk-li"><span class="vk-rank">Полковник</span><b>${l[0].replace(' ','<br>')}</b><span class="small muted">${l[1]}</span><span class="vk-note2">${l[3]===5?'Спрашивает строго за всё: форму, доклады, дисциплину':'Без повода не трогает, но за косяки спросит. Уважать обязательно'}</span></div></article>`};
let vucChk={};
const vucLv=n=>{const l=lvl(n);return `<span class="vk-lv" style="--c:${l.c2}">${l.name}</span>`};
R.vuc=p=>({title:`Военная кафедра (ВУЦ МГУ): уставы, тактика, порядок занятий — ${D.brand}`,after:vucAfter,html:`
<section class="vk-hero" style="--camo:url('${A.spr.camo}')"><div class="wrap"><div class="vk-ht"><p class="kick">Военный учебный центр МГУ · рота 114–116</p><h1 tabindex="-1">Военная кафедра без паники</h1><p class="sub">Расписание пятниц, конспекты по дисциплинам, что говорить на разводе и как докладывать преподавателю.</p><div class="cta"><button class="btn vk-btn btn-xl" data-scroll="vk-disc">Открыть дисциплины</button><button class="btn vk-btnw" data-scroll="vk-fri">Чек-лист к пятнице</button></div></div>
<div class="vk-cats"><figure><div class="bub"><b>Латиша, дежурная по роте</b>«Взвод, встать! Смирно!»</div>${spr('lat_army','Латиша в форме ВКПО')}</figure><figure><div class="bub"><b>Степан, старшина</b>Форма поглажена, шеврон на месте</div>${spr('ste_army','Степан в форме ВКПО')}</figure></div></div></section>
<div class="wrap vk">
<div class="vk-facts">${VUC.facts.map(f=>`<div class="card"><span class="w">${f[0]}</span><h3>${f[1]}</h3><p>${f[2]}</p></div>`).join('')}</div>

<section class="sec"><div class="sec-head"><h2 class="sec-t">Руководство</h2></div><div class="vk-lead">${LEAD.map(leadCard).join('')}</div></section>

<section class="sec" id="vk-disc"><div class="sec-head"><h2 class="sec-t">Дисциплины</h2></div><p class="sec-sub">Открой дисциплину: внутри конспекты по темам, отзывы и правка страницы.</p><div class="vk-deck">${VUC.disc.map(d=>`<a class="vk-card" href="/subject/vuc-${d.id}"><span class="vk-ch">${spr('lat_sit_army','')}</span><b>${d.name}</b>${vucLv(typeof WLV==='object'&&WLV['vuc-'+d.id]||2)}<span class="small">${d.what}</span><span class="small vk-more">Конспекты и правка →</span></a>`).join('')}</div><div id="vkD"></div></section>

<section class="sec"><div class="sec-head"><h2 class="sec-t">Развод в 8:20</h2></div><ol class="vk-steps">${VUC.morning.map((m,i)=>`<li><span class="vk-n">${i+1}</span><div><b class="vk-r">${m[0]}</b><p>${m[1]}</p></div></li>`).join('')}</ol></section>

<section class="sec"><div class="sec-head"><h2 class="sec-t">Порядок занятия</h2></div><p class="sec-sub">Листай по шагам: кто что говорит.</p><div class="card pad vk-lesson"><div class="vk-tabs" role="tablist">${VUC.lesson.map((l,i)=>`<button role="tab" data-vks="${i}" aria-selected="${i?'false':'true'}"><span>${i+1}</span>${l[0]}</button>`).join('')}</div><div id="vkS"></div><div class="vk-nav"><button class="btn btn-oo btn-sm" data-vkmv="-1">Назад</button><button class="btn vk-btn btn-sm" data-vkmv="1">Дальше</button></div></div></section>

<section class="sec"><div class="sec-head"><h2 class="sec-t">Если что-то пошло не так</h2></div><div class="vk-cases">${VUC.cases.map(c=>`<div class="card pad"><b>${c[0]}</b><p>${c[1]}</p></div>`).join('')}</div></section>

<section class="sec"><div class="g2"><div class="card pad vk-look"><h2>Внешний вид</h2>${spr('ste_sit_army','','vk-corner')}<ul>${VUC.look.map(x=>`<li>${I.check}<span>${x}</span></li>`).join('')}</ul></div><div class="card pad"><h2>Учёт посещаемости</h2><p class="muted">Отметки в журнале взвода: <b>н</b> — отсутствовал, <b>б</b> — болел, <b>у</b> — уважительная причина. Учёт ведут командиры отделений, взводный сводит его и передаёт преподавателю. По этим спискам подводят итоги семестра.</p><p class="muted" style="margin-top:8px">Если грозит академический отпуск, предупреди заранее. Иначе договор с ВУЦ могут расторгнуть.</p></div></div></section>

<section class="sec"><div class="sec-head"><h2 class="sec-t">Кто за что отвечает во взводе</h2></div><div class="vk-roles">${VUC.roles.map(r=>`<div class="card pad"><b>${r[0]}</b><p class="small muted">${r[1]}</p></div>`).join('')}</div></section>

<section class="sec" id="vk-ranks"><div class="sec-head"><h2 class="sec-t">Звания</h2></div><div class="card pad vk-rank"><div class="vk-rk">${RANKS.map(r=>`<figure>${pogon(r[1])}<figcaption>${r[0]}</figcaption></figure>`).join('')}</div><p class="small muted vk-rl"><span><i class="vk-p1"></i>1 просвет — младшие офицеры</span><span><i class="vk-p2"></i>2 просвета — старшие</span></p></div></section>

<section class="sec" id="vk-fri"><div class="card pad vk-fri"><div><h2>Чек-лист к пятнице</h2><p class="muted small" id="vkC"></p><div class="prog vk-prog"><i id="vkP"></i></div>${VUC.friday.map((x,i)=>`<label class="ck"><input type="checkbox" data-vkc="${i}"><span>${x}</span></label>`).join('')}</div>${spr('lat_sit_army',LN,'vk-fcat')}</div></section>
<p class="small muted vk-note">Страница собрана по опыту занятий роты и не является официальным документом ВУЦ МГУ. Звания и фамилии подставляй свои.</p>
</div>`});
function vucDisc(id){const d=VUC.disc.find(x=>x.id===id),box=$('#vkD');$$('[data-vkd]').forEach(b=>b.setAttribute('aria-expanded',b.dataset.vkd===id&&box.dataset.open!==id));if(box.dataset.open===id){box.dataset.open='';box.innerHTML='';return}box.dataset.open=id;box.innerHTML=`<article class="card pad vk-open"><div class="hh between"><h2>${d.name}</h2>${vucLv(d.lv)}</div><p class="muted">${d.what}</p>${d.points.map(p=>`<details class="doc"><summary>${p[0]}</summary><p>${p[1]}</p></details>`).join('')}<h3 style="margin-top:14px">Что сделать</h3><ol class="vk-ol">${d.tasks.map(t=>`<li>${t}</li>`).join('')}</ol></article>`;box.scrollIntoView({behavior:noMotion?'auto':'smooth',block:'nearest'})}
let vkStep=0;
function vucStep(i){vkStep=Math.max(0,Math.min(VUC.lesson.length-1,i));const l=VUC.lesson[vkStep];$$('[data-vks]').forEach(b=>b.setAttribute('aria-selected',+b.dataset.vks===vkStep));$('#vkS').innerHTML=`<h3>${vkStep+1}. ${l[0]}</h3>${l[1].map(r=>`<div class="vk-say"><span class="vk-who vk-${r[0]==='Преподаватель'?'p':r[0]==='Дежурный'?'d':'v'}">${r[0]}</span><span>${r[1]}</span></div>`).join('')}`}
function vucChkDraw(){const n=VUC.friday.length,k=VUC.friday.filter((x,i)=>vucChk[i]).length;$('#vkC').textContent=k===n?'Готов к пятнице':`Готово ${k} из ${n}`;$('#vkP').style.width=Math.round(k/n*100)+'%';$$('[data-vkc]').forEach(c=>c.checked=!!vucChk[c.dataset.vkc])}
function vucAfter(){vucStep(0);vucChkDraw();const m=$('#main');
 m.querySelectorAll('[data-vkd]').forEach(b=>b.onclick=()=>vucDisc(b.dataset.vkd));
 m.querySelectorAll('[data-vks]').forEach(b=>b.onclick=()=>vucStep(+b.dataset.vks));
 m.querySelectorAll('[data-vkmv]').forEach(b=>b.onclick=()=>vucStep(vkStep+ +b.dataset.vkmv));
 m.querySelectorAll('[data-vkc]').forEach(c=>c.onchange=()=>{vucChk[c.dataset.vkc]=c.checked;vucChkDraw()});
 m.querySelectorAll('.vk-hero [data-scroll]').forEach(b=>b.onclick=()=>{const t=document.getElementById(b.dataset.scroll);t&&t.scrollIntoView({behavior:noMotion?'auto':'smooth'})});}

const CHECK=/*CHECK_START*/[["Главное видно на первом экране", "Заголовок и кнопка регистрации укладываются в первый экран 390×844 и 1280×800.", true], ["Гость видит только главную", "На всех маршрутах, кроме главной, регистрации, приглашения и правил, гость видит предложение зарегистрироваться. Предметов, отзывов и преподавателей нет.", true], ["Длинные списки с поиском и фильтром", "84 карточки предметов и 61 карточка преподавателей: поиск, курс, фильтры, показ по 12.", true], ["Один факт в одном месте", "Цены, лимиты, контакты, данные преподавателей и сложность предметов хранятся в одном блоке данных.", true], ["Данные преподавателя связаны", "Правка на карточке сразу меняет предмет, игровую карточку, поиск и распределение по курсам.", true], ["Одна главная CTA на странице", "На каждой странице одна главная кнопка. На главной для гостя все кнопки ведут на регистрацию.", true], ["Регистрация за 2 клика", "Кнопка есть в шапке, на первом экране, после разбора задачи и в конце страницы, на телефоне закреплена снизу. Два клика, оплата не требуется.", true], ["Мобильная версия: кнопки от 44 px", "Измерено больше 1200 интерактивных элементов на ширине 390 px.", true], ["Нет горизонтального скролла", "Проверено на 320, 360, 390, 768, 820, 1024, 1100, 1280 и 1920 px.", true], ["Нет шаблонных текстов", "Заглушек-рыбы и технических пометок на страницах нет.", true], ["Данные настоящие", "Предметы, преподаватели, расписание военки и конспекты ВУЦ взяты из реальных источников. Что не заполнено, так и подписано: «пока не заполнили».", true], ["Уровни доступа работают", "Разделы предмета проверены на всех уровнях: аккаунт, 350, 500, 750 ₽.", true], ["Лимиты трекера работают", "На 350 ₽ создаётся 1 свой проект, на 500 ₽ до 3, на 750 ₽ лимита нет. Проекты по приглашению лимит не расходуют.", true], ["Приглашение без подписки", "Гость проходит по ссылке, регистрируется и попадает в проект с нужной ролью, не платя.", true], ["Диаграмма Ганта и заметки", "Полосы двигаются и растягиваются, задача открывается в окне, срок раньше начала не принимается.", true], ["Отзывы", "Отзыв можно написать от своего имени или анонимно, средняя сложность считается автоматически.", true], ["Правки и внутренние рубли", "Принятая правка меняет конспект и пополняет счёт, счёт уменьшает оплату вплоть до нуля, рублями можно поделиться. Вывода нет.", true], ["Главная продаёт только настоящим", "Числа берутся из данных сайта: количество предметов, цены, лимиты, начисления. Выдуманных отзывов и счётчиков пользователей нет.", true], ["Штрафы", "Значок на кнопке «Кабинет», оплата со счёта, обжалование, назначение администратором только с доказательством, условия показаны при регистрации.", true], ["Лианы не мешают читать", "Проверено на всех ширинах: не пересекают текст и кнопки, увеличены кратно, поэтому не размываются.", true], ["Контраст текста от 4,5:1", "Минимум 4,99:1 (оранжевый на светло-оранжевом), кнопка 5,07:1.", true], ["Без логотипов МГУ и ВШБ", "Логотип сайта свой, в подвале и правилах указано, что проект независимый.", true], ["Фото преподавателей", "Не добавлены: нужно согласие преподавателей. В форме администратора есть загрузка фото.", false]]/*CHECK_END*/;
R.proto=()=>({title:`О прототипе: ${D.brand}`,html:`<div class="wrap"><div class="phead"><h1 tabindex="-1">О прототипе</h1><p class="d">Служебная страница для команды. На финальном сайте её не будет. Переключатель «Доступ» в тёмной полосе показывает сайт глазами гостя, участника, подписчика и администратора. Данные хранятся только в этом браузере.</p></div><div class="g2"><div class="card pad"><h3>Настоящие данные</h3><p class="muted">Перечень дисциплин, преподаватели и мероприятия взяты с сайта школы. Сложность предметов считается из отзывов студентов.</p></div><div class="card pad"><h3>Что заполняют студенты</h3><p class="muted">Конспекты, темы, разбалловку, отзывы и оценки сложности пишут сами студенты, как в Википедии. Правки новичков проверяет администратор.</p></div></div><section class="sec"><div class="sec-head"><h2 class="sec-t">Персоны и пути</h2></div><div class="g3">${PERSONAS.map(x=>`<article class="card pad pers"><h3>${x.name}, ${x.who}</h3><dl><div><dt>Боль</dt><dd>${x.pain}</dd></div><div><dt>Триггер</dt><dd>${x.trigger}</dd></div><div><dt>Возражение</dt><dd>${x.obj}</dd></div><div><dt>Что заставит заплатить</dt><dd>${x.pay}</dd></div></dl><div class="path">${x.path.map(s=>`<a href="${s[2]}">${s[0]}<small>${s[1]}</small></a>`).join('')}</div></article>`).join('')}</div></section><section class="sec"><div class="sec-head"><h2 class="sec-t">Чек-лист юзабилити</h2></div><div class="card pad"><ul class="chk">${CHECK.map(c=>`<li class="${c[2]?'':'part'}">${c[2]?I.check:I.warn}<div><b>${c[0]}</b><span>${c[1]}</span></div></li>`).join('')}</ul></div></section><section class="sec"><div class="sec-head"><h2 class="sec-t">Аудит удобства</h2></div><div class="card pad"><ul class="chk">${AUDIT.map(a=>`<li>${I.check}<div><b>${a[0]}</b><span>${a[1]}</span></div></li>`).join('')}</ul></div></section><section class="sec"><div class="sec-head"><h2 class="sec-t">Источники</h2></div><ul>${SOURCES.map(s=>`<li><a class="link" href="${s[1]}" target="_blank" rel="noopener">${s[0]}</a></li>`).join('')}</ul></section></div>`});
R.notfound=()=>({title:`Страница не найдена: ${D.brand}`,html:`<div class="wrap"><div class="card done">${spr('lat_sad',LN)}<h1 tabindex="-1" class="h1">Такой страницы нет</h1><p class="muted">${HELP} поискала и не нашла. Проверь ссылку или открой каталог.</p><a class="btn btn-o cta1" href="/subjects">Перейти к предметам</a></div></div>`});

