const tgTxt=p=>{const s=byId(p.sid);return p.status==='ok'?`Правку «${propTitle(p)}» по предмету «${s.name}» приняли. +${rub(p.amount)} на счёт`:`Правку «${propTitle(p)}» по предмету «${s.name}» отклонили. Причина: ${noDot(p.reason)}.`};
const SEED_DONE=S.props.filter(p=>p.status!=='pending');
S.tg=ST('tg',null)||{on:true,msgs:SEED_DONE.filter(p=>p.by===ME).map(p=>({t:tgTxt(p),at:addD(p.at,1)})).sort((a,b)=>a.at<b.at?-1:1)};
S.jlog=ST('jlog',null)||[{at:addD(T0,-30),tm:'18:40',t:'Отменил штраф @student «Оскорбления и личные данные в отзывах»: номер оказался собственным',ex:1},...SEED_DONE.map((p,i)=>({at:addD(p.at,1),tm:['12:05','21:17','09:52','16:30'][i%4],t:decTxt(p),ex:1}))].sort((a,b)=>a.at<b.at?-1:1);
const jlog=t=>{const d=new Date();S.jlog.push({at:T0,tm:String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'),t});saveK('jlog')};
const tgPush=t=>{if(!S.tg.on)return;S.tg.msgs.push({t,at:T0});saveK('tg')};
const bonusOf=p=>(p.bonus||[]).reduce((a,b)=>a+b.a,0);

/* --- Контент, отредактированный админом, поверх исходных данных --- */
const ORIG={};SUBJECTS.forEach(s=>ORIG[s.id]={about:s.about,topics:(s.topics||[]).map(x=>[...x]),tasks:[...(s.tasks||[])]});
function applyCEdit(id){const ids=id?[id]:Object.keys(S.cEdit);ids.forEach(k=>{const s=byId(k),e=S.cEdit[k]||ORIG[k];if(!s||!e)return;s.about=e.about;s.topics=e.topics.map(x=>[...x]);s.tasks=[...e.tasks]})}
applyCEdit();

/* ===== Предметы: прогресс ===== */
function progOf(s){if(!s||!s.full)return null;const ts=topicsOf(s),r=S.read[s.id]||[],c=S.course[s.id]||[],q=S.quiz[s.id],nt=s.topics.length;
 const read=[ts.filter((x,i)=>r[i]).length,ts.length],course=[s.topics.filter((x,i)=>c[i]).length,nt],quiz=q?[q.best,q.n]:[0,ts.filter((x,i)=>(noteText(s,i)||'').length>12).length];
 const f=v=>v[1]?v[0]/v[1]:0;return{read,course,quiz,p:Math.round((f(read)+f(course)+f(quiz))/3*100)}}
const progCard=s=>{const g=progOf(s);if(!g)return '';const row=(l,v,tab,need)=>`<div class="pg-r"><div class="top"><span>${l}</span><b>${v[0]} из ${v[1]}</b></div><div class="w-b"><i style="width:${v[1]?v[0]/v[1]*100:0}%"></i></div>${need&&!has(need)?`<span class="small muted">Откроется по тарифу от ${rub(D.access[need])}</span>`:`<button class="link" data-tabgo="${tab}">Открыть</button>`}</div>`;
 return `<div class="card pad pg"><div class="pg-h"><b>Готовность к экзамену</b><span class="pg-n">${g.p}%</span></div><div class="prog"><i style="width:${g.p}%"></i></div>${row('Прочитано тем',g.read,'notes','notes')}${row('Пройдено этапов курса',g.course,'course','course')}${row('Тренажёр, лучший результат',g.quiz,'trainer','trainer')}</div>`};
function refreshSide(){if(!curS)return;const c=$('.side .pg');if(c)c.outerHTML=progCard(curS);const d=$('.side .dlc');if(d)d.outerHTML=dlCard(curS)}

/* ===== Предметы: дедлайны ===== */
const SES_Z='2026-12-21',SES_E='2027-01-11';
function dlSeed(s){if(!s.full)return [];const h=hsh(s.id),o=[];if(s.control!=='Зачёт')o.push({t:'Контрольная',d:addD(T0,6+h%20),ex:1});o.push({t:s.control||'Зачёт',d:s.control==='Экзамен'?addD(SES_E,h%14):addD(SES_Z,h%9),ex:1});return o}
let dlOf=s=>[...dlSeed(s),...(S.dl[s.id]||[]).map((x,k)=>({...x,own:1,k}))].sort((a,b)=>a.d<b.d?-1:1);
const dlWhen=d=>{const n=dDiff(T0,d);return n<0?'прошло':n===0?'сегодня':n===1?'завтра':`через ${plural(n,'день','дня','дней')}`};
const dlCard=s=>{const a=dlOf(s);return `<div class="card pad dlc"><div class="pg-h"><b>Дедлайны</b>${a.length?`<button class="link" data-ics="${s.id}">${I_CAL} Всё в календарь</button>`:''}</div>${a.length?a.map((x,i)=>`<div class="dl-r ${x.d<T0?'past':''}"><span><b>${esc(x.t)}</b><small>${fmtD(x.d)}${x.tm?', '+x.tm:''}, ${dlWhen(x.d)}${x.md?' · Moodle':''}</small></span><span class="dl-a"><button class="ib" data-ics1="${s.id}|${i}" aria-label="Добавить «${esc(x.t)}» в календарь">${I_CAL}</button>${x.own?`<button class="ib" data-dldel="${s.id}|${x.k}" aria-label="Удалить «${esc(x.t)}»">${I.x}</button>`:''}</span></div>`).join(''):'<p class="small muted">Дат пока нет.</p>'}<form class="dl-f" data-dladd="${s.id}" novalidate><input type="text" name="t" placeholder="Что сдаём" maxlength="40" aria-label="Что сдаём"><input type="date" name="d" aria-label="Дата" min="${T0}"><button class="btn btn-oo btn-sm">Добавить дату</button></form></div>`};
function icsDownload(items,name){const d=x=>x.replace(/-/g,''),e=t=>String(t).replace(/[\\,;]/g,m=>'\\'+m),L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//latisha.ru//RU','CALSCALE:GREGORIAN'];
 items.forEach((x,i)=>L.push('BEGIN:VEVENT',`UID:${d(x.d)}-${i}-${hsh(x.t+(x.s||''))}@latisha.ru`,`DTSTAMP:${d(T0)}T090000Z`,`DTSTART;VALUE=DATE:${d(x.d)}`,`DTEND;VALUE=DATE:${d(addD(x.d,1))}`,`SUMMARY:${e((x.s?x.s+': ':'')+x.t)}`,'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY',`DESCRIPTION:${e('Завтра: '+x.t)}`,'END:VALARM','END:VEVENT'));
 L.push('END:VCALENDAR');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([L.join('\r\n')],{type:'text/calendar'}));a.download=name+'.ics';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);goal('ics_download');toast(plural(items.length,'дата','даты','дат')+' в файле календаря: открой его, и они появятся в календаре')}

/* ===== Мой семестр на главной ===== */
const mySem=()=>SUBJECTS.filter(s=>s.sems&&s.sems.includes(+S.me.sem));
let mineAll=false;
const myFav=()=>S.fav.map(byId).filter(Boolean);
function homeMine(){const list=myFav(),pp=s=>(progOf(s)||{p:0}).p,shown=mineAll?list:list.slice(0,7),dls=list.flatMap(s=>dlOf(s).filter(x=>x.d>=T0).map(x=>({...x,s:s.name,sid:s.id}))).sort((a,b)=>a.d<b.d?-1:1),avg=list.length?Math.round(list.reduce((a,s)=>a+pp(s),0)/list.length):0;
 if(!list.length)return `<section class="sec" id="mine"><div class="sec-head"><h2 class="sec-t">Мои предметы</h2></div><div class="card empty mine-e">${spr('lat_read',LN)}<h3>Здесь будут твои предметы</h3><p class="muted">Открой предмет и нажми «В мои предметы». Он появится здесь с прогрессом и дедлайнами.</p><a class="btn btn-o cta1" href="/subjects">Выбрать предметы</a></div></section>`;
 return `<section class="sec" id="mine"><div class="sec-head"><h2 class="sec-t">Мои предметы</h2><a class="more" href="/subjects">Добавить ещё</a></div><div class="mine-g"><div class="card pad"><div class="pg-h"><h3>${plural(list.length,'предмет','предмета','предметов')}</h3><span class="small muted">Готовность в среднем ${avg}%</span></div>${shown.map(s=>{const g=progOf(s);return `<a class="mrow" href="/subject/${s.id}"><span class="mn">${esc(s.name)}</span><span class="mbar"><i style="width:${g?g.p:0}%"></i></span><b>${g?g.p:0}%</b></a>`}).join('')}${list.length>7?`<button class="link" data-mineall="1" aria-expanded="${mineAll}">${mineAll?'Свернуть':`Показать все ${list.length}`}</button>`:''}</div><div class="card pad"><h3>Ближайшие дедлайны</h3>${dls.length?dls.slice(0,6).map(x=>`<a class="dl" href="/subject/${x.sid}"><span><b>${esc(x.t)}</b><small>${esc(x.s)}${x.ex?' · пример':''}</small></span><span class="dr">${fmtD(x.d)}, ${dlWhen(x.d)}</span></a>`).join('')+`<button class="btn btn-oo btn-sm" data-icsall="1" style="margin-top:12px">${I_CAL} Все дедлайны в календарь</button>`:'<p class="muted small">Дедлайнов нет. Добавь дату на странице предмета.</p>'}</div></div></section>`}

/* ===== Поиск по тексту конспектов ===== */
function noteHits(){const rows=$('#rows');if(!rows)return;let box=$('#nHits');if(!box){box=document.createElement('section');box.id='nHits';box.className='sec';rows.after(box)}const q=norm(cat.q.trim());if(q.length<3){box.innerHTML='';return}
 const hits=[];SUBJECTS.forEach(s=>topicsOf(s).forEach((x,i)=>{const tx=noteText(s,i)||'',inT=norm(x[0]).includes(q);if(inT||norm(tx).includes(q))hits.push({s,i,title:x[0],tx,inT})}));hits.sort((a,b)=>b.inT-a.inT);
 const mark=t=>{const k=norm(t).indexOf(q);if(k<0)return esc(t.length>150?t.slice(0,150)+'…':t);const a=Math.max(0,k-60),z=Math.min(t.length,k+q.length+80);return (a?'…':'')+esc(t.slice(a,k))+'<mark>'+esc(t.slice(k,k+q.length))+'</mark>'+esc(t.slice(k+q.length,z))+(z<t.length?'…':'')};
 box.innerHTML=hits.length?`<div class="sec-head"><h2 class="sec-t">Найдено в конспектах</h2><span class="muted small">${plural(hits.length,'совпадение','совпадения','совпадений')}</span></div><div class="card pad nh">${hits.slice(0,12).map(h=>`<a class="nh-r" href="/subject/${h.s.id}?tab=notes&topic=${h.i}"><b>${mark(h.title)}</b><small class="muted">${esc(h.s.name)}</small>${has('notes')?`<span class="small">${mark(h.tx)}</span>`:''}</a>`).join('')}${hits.length>12?`<p class="small muted">Показаны первые 12. Уточни запрос.</p>`:''}${has('notes')?'':`<p class="small muted">Текст конспектов откроется по тарифу от ${rub(D.access.notes)}. Сейчас видны только названия тем.</p>`}</div>`:''}

/* ===== Тренажёр: реши, проверь, разбор ===== */
const QZ={};
function qzBuild(id,qs){return QZ[id]={qs,i:0,pick:null,checked:false,ok:0,wrong:[]}}
function qzHtml(id){const z=QZ[id];if(!z)return '';const n=z.qs.length;
 if(z.i>=n)return `<div class="qz" data-qz="${id}"><div class="qz-res"><span class="qz-big">${z.ok} из ${n}</span><p class="muted">${z.ok===n?'Без ошибок. Можно идти сдавать.':z.ok>=n*0.7?'Хорошо. Повтори ошибки ниже и пройди ещё раз.':'Стоит перечитать конспект и пройти ещё раз.'}</p>${z.wrong.length?`<div class="qz-wr"><b>Где ошибка</b>${z.wrong.map(w=>{const q=z.qs[w];return `<div class="li"><span class="small muted">${esc(q.q)}</span><br>Правильно: <b>${esc(q.opts[q.a])}</b>${q.link?` <a class="link" href="${q.link}">повторить</a>`:''}</div>`}).join('')}</div>`:''}<button class="btn btn-o btn-sm" data-qzagain="1">Пройти ещё раз</button></div></div>`;
 const q=z.qs[z.i],right=z.pick===q.a;return `<div class="qz" data-qz="${id}"><div class="qz-top"><span class="small muted">Вопрос ${z.i+1} из ${n}</span><span class="small muted">Верно: ${z.ok}</span></div><div class="prog qz-p"><i style="width:${z.i/n*100}%"></i></div><p class="qz-q">${esc(q.q)}</p><div class="qz-o" role="radiogroup" aria-label="Варианты ответа">${q.opts.map((o,k)=>{const c=z.checked?(k===q.a?'ok':k===z.pick?'bad':''):k===z.pick?'sel':'';return `<button type="button" class="qz-b ${c}" role="radio" aria-checked="${k===z.pick}" data-qzpick="${k}" ${z.checked?'disabled':''}>${esc(o)}</button>`}).join('')}</div>${z.checked?`<div class="qz-why ${right?'ok':'bad'}" role="status"><b>${right?'Верно':'Неверно'}</b>${q.why?`<p>${esc(q.why)}</p>`:''}${q.link?`<a class="link" href="${q.link}">${q.linkT||'Открыть в конспекте'}</a>`:''}</div><button type="button" class="btn btn-o btn-sm" data-qznext="1">${z.i+1<n?'Дальше':'Посмотреть результат'}</button>`:`<button type="button" class="btn btn-o btn-sm" data-qzcheck="1" ${z.pick==null?'disabled':''}>Проверить</button>`}</div>`}
function subjQs(s){const ts=topicsOf(s).map((x,i)=>({t:x[0],d:noteText(s,i),i})).filter(x=>x.d&&x.d.length>12),pool=ts.map(x=>x.t),oth=shuf(SUBJECTS.filter(o=>o.id!==s.id&&o.full&&kindOf(o)===kindOf(s)).flatMap(o=>(o.topics||[]).map(x=>x[0])));
 return shuf(ts).map(x=>{let w=pool.filter(t=>t!==x.t);if(w.length<3)w=w.concat(oth.filter(t=>t!==x.t&&!w.includes(t)).slice(0,3-w.length));const opts=shuf([x.t,...shuf(w).slice(0,3)]);return{q:`О какой теме это: «${x.d}»`,opts,a:opts.indexOf(x.t),why:`Это тема «${x.t}».`,link:has('notes')?`/subject/${s.id}?tab=notes&topic=${x.i}`:'',linkT:'Повторить в конспекте'}})}
function trainerHtml(s){const id='s_'+s.id;if(!QZ[id]){const z=qzBuild(id,subjQs(s));z.rebuild=()=>subjQs(s);z.done=z=>{const q=S.quiz[s.id]||{best:0};q.n=z.qs.length;q.last=z.ok;q.best=Math.max(q.best||0,z.ok);q.at=T0;S.quiz[s.id]=q;saveK('quiz');refreshSide()}}const q=S.quiz[s.id];
 return `<section class="card pad"><div class="hh between"><h2>Тренажёр</h2>${spr('lat_sit',LN,'corner')}</div><p class="muted small">Выбери ответ, нажми «Проверить» и посмотри разбор.${q?` Лучший результат: ${q.best} из ${q.n}, последний: ${q.last} из ${q.n}.`:''}</p>${qzHtml(id)}</section>`}

/* --- Обёртки функций предмета --- */
const _tabHtml=tabHtml;tabHtml=function(s,t){if(t==='trainer'&&s.full&&has('trainer'))return trainerHtml(s);return _tabHtml(s,t)};
const _tabSet=tabSet;tabSet=function(t){_tabSet(t);if(t==='notes'&&curS&&has('notes'))enhanceNotes(curS)};
function enhanceNotes(s){const r=S.read[s.id]||[];$$('#tabC details.doc').forEach((d,i)=>{const f=$('.doc-f',d);if(!f||$('.rd',d))return;const l=document.createElement('label');l.className='rd';l.innerHTML=`<input type="checkbox" data-read="${i}" ${r[i]?'checked':''}><span>Прочитал</span>`;f.prepend(l);d.classList.toggle('done',!!r[i])})}
const _RS=R.subject;R.subject=(p,id)=>{const v=_RS(p,id),s=byId(id);if(!s||!S.auth||!v.html.includes('<aside class="side">'))return v;S.views[id]=(S.views[id]||0)+1;saveK('views');
 v.html=v.html.replace('<aside class="side">','<aside class="side">'+progCard(s)+dlCard(s));const af=v.after;v.after=()=>{af&&af();if(p.topic!=null&&curT==='notes'){const d=$$('#tabC details.doc')[+p.topic];if(d){d.open=true;d.classList.add('hl');setTimeout(()=>d.scrollIntoView({block:'center'}),60)}}};return v};
const _catDraw=catDraw;catDraw=function(){_catDraw();noteHits()};
const _RH=R.home;R.home=(...a)=>{const v=_RH(...a);if(!S.auth||!v.html)return v;const k=v.html.indexOf('<section class="sec"><div class="sec-head"><h2 class="sec-t">Как это работает</h2>');if(k>=0)v.html=v.html.slice(0,k)+homeMine()+v.html.slice(k);return v};

/* ===== Правки: история с этапами и уведомления ===== */
function myPropsHtml(n){const mine=S.props.filter(p=>p.by===ME).slice().reverse().slice(0,n||99);return mine.length?mine.map(p=>{const s=byId(p.sid),fin=p.status!=='pending',ok=p.status==='ok',bon=bonusOf(p);return `<div class="ph-r"><div class="ph-h"><b>${esc(s.name)}: ${esc(propTitle(p))}</b><span class="small muted">${TYPES[p.type]}, ${fmtD(p.at)}</span></div><ol class="tl" aria-label="Этапы правки"><li class="on">Отправлено</li><li class="on ${fin?'':'cur'}">На проверке</li><li class="${fin?(ok?'on ok':'on no'):''}">${fin?(ok?`Принято, +${rub(p.amount)}`:'Отклонено'):'Решение'}</li>${bon?`<li class="on ok">Доначислено +${rub(bon)}</li>`:''}</ol>${p.reason?`<p class="small">Причина: ${esc(noDot(p.reason))}.</p>`:''}</div>`}).join(''):'<p class="muted">Правок пока нет. Открой конспект и нажми «Предложить правку».</p>'}
const tgBox=()=>`<section class="card pad tgb"><div class="pg-h"><h2>Уведомления в Telegram</h2><label class="sw"><input type="checkbox" id="tgOn" ${S.tg.on?'checked':''}><span>Присылать в @${D.bot}</span></label></div><div class="tgchat" aria-live="polite">${S.tg.msgs.slice(-4).map(m=>`<div class="tgm"><b>@${D.bot}</b><p>${esc(m.t)}</p><small>${fmtD(m.at)}</small></div>`).join('')||'<p class="muted small">Сообщений пока нет.</p>'}</div><p class="small muted">${EX} Бот пишет, когда правку приняли, отклонили или доначислили рубли.</p></section>`;
const _RAcc=R.account;R.account=(...a)=>{const v=_RAcc(...a);if(!S.auth||!v.html.includes('Кабинет'))return v;v.html=v.html.replace(/<\/div>$/,`<section class="sec"><div class="sec-head"><h2 class="sec-t">Мои правки</h2><a class="more" href="/contrib">Весь вклад</a></div><div class="card pad">${myPropsHtml(4)}</div></section><section class="sec">${tgBox()}</section></div>`);return v};
const _RC=R.contrib;R.contrib=(...a)=>{const v=_RC(...a),m='<section class="sec"><div class="sec-head"><h2 class="sec-t">Мои правки</h2></div>',k=v.html.indexOf(m),z=v.html.indexOf('<section class="sec"><div class="sec-head"><h2 class="sec-t">Сколько начисляем');if(k>=0&&z>k)v.html=v.html.slice(0,k)+`${m}<div class="card pad">${myPropsHtml()}</div></section><section class="sec">${tgBox()}</section>`+v.html.slice(z);return v};
const _decide=decide;decide=function(id,ok,card){const p=S.props.find(x=>x.id==id),was=p&&p.status;_decide(id,ok,card);if(!p||p.status===was)return;jlog(decTxt(p));if(p.by===ME)tgPush(tgTxt(p))};

/* ===== Админка: сводка, массовые действия, было/стало, доначисление, журнал, контент ===== */
const XT=[['apps','Заявки'],['dash','Сводка'],['log','Журнал'],['content','Контент']];
const xTabs=(t,q)=>adminTabs(XT.some(x=>x[0]===t)?'none':t,q).replace('aria-label="Разделы модерации">',`aria-label="Разделы модерации"><a class="tab" href="/admin?tab=apps" ${t==='apps'?'aria-current="page"':''}>Заявки${appsPending()?` <span class="cnt">${appsPending()}</span>`:''}</a><a class="tab" href="/admin?tab=dash" ${t==='dash'?'aria-current="page"':''}>Сводка</a>`).replace('</nav>',`<a class="tab" href="/admin?tab=log" ${t==='log'?'aria-current="page"':''}>Журнал</a><a class="tab" href="/admin?tab=content" ${t==='content'?'aria-current="page"':''}>Контент</a></nav>`);
