    if (wJ(m[k]) === wJ(b[k])) continue;                       // автор не трогал
    if ((k === 'topics' || k === 'materials') && Array.isArray(m[k])) { const r = wMergeList(b[k], c[k], m[k]); out[k] = r.v; conflict = conflict || r.conflict; continue; }
