const TIER_N={0:'Бесплатный',350:'Базовый · 350 ₽',500:'Сессия · 500 ₽',750:'Максимум · 750 ₽'};
const ago=ms=>{if(!ms)return 'ещё не заходил';const m=Math.round((Date.now()-ms)/60000);return m<10?'сейчас на сайте':m<60?`${m} мин назад`:m<1440?`${Math.round(m/60)} ч назад`:fmtDT(ms)};
function usersHtml(){setTimeout(loadUsers,0);return `<section id="admU"><div class="card pad"><p class="muted">Загружаю пользователей…</p></div></section>`}
async function loadUsers(){const box=$('#admU');if(!box)return;await API_READY;
 if(!(API_ON&&apiRole()==='admin')){box.innerHTML='<div class="card pad"><p>Пользователи хранятся на сервере. Сейчас сервер не отвечает или ты вошёл без него: включи ПК с сервером и войди заново.</p></div>';return}
 if(!(window.API_H&&API_H.wiki>=3)){box.innerHTML='<div class="card pad"><p>Сервер старой версии и ещё не умеет управлять пользователями. Перезапусти его: <b>restart.bat</b> от имени администратора.</p></div>';return}
 try{ADM_U=(await api('/api/admin/users')).users;drawUsers()}catch(x){box.innerHTML=`<div class="card pad"><p>${esc(x.message)}</p></div>`}}
function userCard(u){const fines=(u.fines||[]).filter(f=>!f.off);
 return `<article class="card pad au ${u.blocked?'blocked':''}" data-au="${esc(u.login)}"><div class="au-h"><div><b class="au-n">${esc(u.login)}</b> <span class="muted">${esc(u.tg||'')}</span></div><div class="au-tags">${u.blocked?'<span class="tag bad">Заблокирован</span>':''}<span class="tag ${u.tier?'live':''}">${TIER_N[u.tier||0]}</span>${u.edits>=5?'<span class="tag">Опытный автор</span>':''}</div></div>
 <dl class="ap-d au-d"><div><dt>Баланс</dt><dd><b>${rub(u.wallet||0)}</b></dd></div><div><dt>Правок принято</dt><dd>${u.edits||0}${u.pending?`, ждут ${u.pending}`:''}</dd></div><div><dt>Отзывов</dt><dd>${u.reviews||0}</dd></div><div><dt>С нами с</dt><dd>${u.at?fmtD(iso(new Date(u.at))):'—'}</dd></div><div><dt>Был</dt><dd>${ago(u.seen)}</dd></div></dl>
 <div class="au-g"><label class="fl">Тариф<select class="f" data-autier>${[0,350,500,750].map(t=>`<option value="${t}" ${t===(u.tier||0)?'selected':''}>${TIER_N[t]}</option>`).join('')}</select></label>
 <div class="au-f"><span class="fl">Деньги</span><div class="wk-row"><input type="number" class="au-amt" min="1" step="10" placeholder="Сумма, ₽" aria-label="Сумма"><input type="text" class="au-why" maxlength="140" placeholder="За что (увидит студент)" aria-label="Комментарий"><button type="button" class="btn btn-o btn-sm" data-aumoney="1">Начислить</button><button type="button" class="btn btn-oo btn-sm" data-aumoney="-1">Списать</button></div></div>
 <div class="au-f"><span class="fl">Штраф</span><div class="wk-row"><input type="number" class="au-famt" min="1" step="10" placeholder="Сумма, ₽" aria-label="Сумма штрафа"><input type="text" class="au-fwhy" maxlength="200" placeholder="Причина: её увидит студент" aria-label="Причина штрафа"><button type="button" class="btn btn-oo btn-sm au-bad" data-aufine>Оштрафовать</button></div>${fines.length?`<ul class="au-fl">${fines.map(f=>`<li><span>${rub(f.amount)} · ${esc(f.reason)} <small class="muted">${fmtDT(f.at)}</small></span><button type="button" class="link" data-auunfine="${f.id}">Отменить</button></li>`).join('')}</ul>`:''}</div></div>
 <details class="au-more"><summary>История кошелька, заметка, пароль и блокировка</summary>${(u.wlog||[]).length?`<ul class="au-log">${[...u.wlog].reverse().map(x=>`<li><span>${esc(x[0])}</span><b class="${x[1]<0?'neg':'pos'}">${x[1]>0?'+':''}${rub(x[1])}</b><small class="muted">${fmtDT(x[2])}</small></li>`).join('')}</ul>`:'<p class="small muted">Операций по кошельку пока нет.</p>'}
 <label class="fl">Заметка администратора (студент не видит)<textarea rows="2" class="au-note" maxlength="500">${esc(u.note||'')}</textarea></label>
 <div class="wk-row"><button type="button" class="btn btn-oo btn-sm" data-aunote>Сохранить заметку</button><button type="button" class="btn btn-oo btn-sm" data-aupass ${u.hasTg?'':'disabled'}>Сбросить пароль через бота</button><button type="button" class="btn btn-oo btn-sm au-bad" data-aublock="${u.blocked?0:1}">${u.blocked?'Разблокировать':'Заблокировать'}</button></div></details></article>`}
function drawUsers(){const box=$('#admU');if(!box||!ADM_U)return;const q=norm(admUQ.trim()),list=ADM_U.filter(u=>(admUT==='all'||String(u.tier||0)===admUT||(admUT==='blocked'&&u.blocked))&&(!q||norm(u.login+' '+(u.tg||'')+' '+(u.note||'')).includes(q)));
 const by=t=>ADM_U.filter(u=>(u.tier||0)===t).length,sum=ADM_U.reduce((a,u)=>a+(u.wallet||0),0),foc=document.activeElement&&document.activeElement.id==='auQ';
 box.innerHTML=`<div class="kpis au-k"><div class="card pad"><span class="small muted">Всего</span><b>${ADM_U.length}</b></div><div class="card pad"><span class="small muted">Платные тарифы</span><b>${by(350)+by(500)+by(750)}</b><span class="small muted">350: ${by(350)} · 500: ${by(500)} · 750: ${by(750)}</span></div><div class="card pad"><span class="small muted">На кошельках</span><b>${rub(sum)}</b></div><div class="card pad"><span class="small muted">Заблокировано</span><b>${ADM_U.filter(u=>u.blocked).length}</b></div></div>
 <div class="au-bar"><input type="search" id="auQ" value="${esc(admUQ)}" placeholder="Логин, ник в Telegram или заметка" aria-label="Поиск пользователя"><div class="tags">${[['all','Все'],['0','Бесплатный'],['350','350'],['500','500'],['750','750'],['blocked','Заблокированные']].map(([k,l])=>`<button type="button" class="tab" data-aut="${k}" aria-pressed="${admUT===k}">${l}</button>`).join('')}</div></div>
 <div class="stack" id="auList">${list.length?list.map(userCard).join(''):`<div class="card pad empty"><p>${ADM_U.length?'Никого не нашлось. Измени поиск или фильтр.':'Пользователей пока нет. Они появятся, когда ты примешь первые заявки из бота.'}</p></div>`}</div>`;
 if(foc){const i=$('#auQ');i.focus();i.setSelectionRange(i.value.length,i.value.length)}}
async function admUDo(login,act,body,okMsg){try{const r=await api(`/api/admin/users/${login}/${act}`,body);const i=ADM_U.findIndex(u=>u.login===login);if(i>=0&&r.user)ADM_U[i]=r.user;drawUsers();jlog(`${okMsg}: ${login}`);toast(okMsg+(act==='password'&&!r.sent?'. Telegram не привязан':''))}catch(x){toast(x.message)}}
document.addEventListener('input',e=>{if(e.target.id==='auQ'){admUQ=e.target.value;clearTimeout(drawUsers.t);drawUsers.t=setTimeout(drawUsers,180)}});
document.addEventListener('change',e=>{const s=e.target.closest('[data-autier]');if(!s)return;const c=s.closest('.au');admUDo(c.dataset.au,'tier',{tier:+s.value},`Тариф изменён на «${TIER_N[+s.value]}»`)});
document.addEventListener('click',e=>{let b;const c=e.target.closest('.au'),lg=c&&c.dataset.au;
 if(b=e.target.closest('[data-aut]')){admUT=b.dataset.aut;drawUsers();return}
 if(!c)return;
 if(b=e.target.closest('[data-aumoney]')){const a=Math.abs(Math.round(+$('.au-amt',c).value||0)),sg=+b.dataset.aumoney;if(!a){toast('Укажи сумму');$('.au-amt',c).focus();return}admUDo(lg,'money',{amount:a*sg,note:$('.au-why',c).value.trim()},sg>0?`Начислено ${rub(a)}`:`Списано ${rub(a)}`);return}
 if(e.target.closest('[data-aufine]')){const a=Math.round(+$('.au-famt',c).value||0),w=$('.au-fwhy',c).value.trim();if(a<=0){toast('Укажи сумму штрафа');$('.au-famt',c).focus();return}if(!w){toast('Напиши причину штрафа: её увидит студент');$('.au-fwhy',c).focus();return}admUDo(lg,'fine',{amount:a,reason:w},`Штраф ${rub(a)} назначен`);return}
 if(b=e.target.closest('[data-auunfine]')){admUDo(lg,'unfine',{id:b.dataset.auunfine},'Штраф отменён, деньги возвращены');return}
 if(e.target.closest('[data-aunote]')){admUDo(lg,'note',{note:$('.au-note',c).value},'Заметка сохранена');return}
 if(e.target.closest('[data-aupass]')){if(confirm(`Сбросить пароль ${lg}? Бот пришлёт ему новый, старый перестанет работать.`))admUDo(lg,'password',{},'Новый пароль отправлен в Telegram');return}
 if(b=e.target.closest('[data-aublock]')){const on=b.dataset.aublock==='1';let why='';if(on){why=prompt(`Заблокировать ${lg}? Напиши причину: её увидит студент.`,'');if(why===null)return}admUDo(lg,'block',{on,reason:why},on?'Аккаунт заблокирован':'Аккаунт разблокирован');return}});
