 <section class="sec"><div class="cb-ts">${tile('/','★','Мои предметы',S.fav.length?plural(S.fav.length,'предмет','предмета','предметов'):'пока пусто')}${has('tracker')?tile('/projects','▦','Проекты',''):''}${tile('/teachers','☺','Преподаватели','')}${tile('/vuc','✪','Военка','')}${tile('/events','◷','Мероприятия','')}</div></section>
