/* преподаватели: фильтр по сложности */
fc.lv='';
fcDraw=function(){const box=$('#frows');if(!box)return;const q=norm(fc.q.trim()),a=allT().filter(t=>(!q||norm(t.name+' '+t.disc.join(' ')).includes(q))&&(!fc.d||t.dept===fc.d)&&(!fc.c||tCourses(t).includes(+fc.c))&&(!fc.lv||(fc.lv==='0'?!t.lv:t.lv===+fc.lv)));if(fc.lv&&fc.lv!=='0')a.sort((x,y)=>(y.stars||0)-(x.stars||0));$('#cnt').textContent=`Найдено: ${a.length}`;$('#reset').hidden=!(fc.q||fc.d||fc.c||fc.lv);$$('.seg button[data-tc]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tc===fc.c));const sl=$('#flv');if(sl)sl.value=fc.lv;box.innerHTML=a.length?`<div class="deck tdeck">${a.slice(0,fc.n).map(realCard).join('')}</div>`:latEmpty('Никого не нашли',fc.lv?'С таким уровнем пока никого: уровень появляется после отзывов студентов.':`${HELP} проверила весь список. Попробуй другую фамилию или сбрось фильтры.`,'lat_sad');const m=$('#more');m.hidden=a.length<=fc.n;m.textContent=`Показать ещё ${Math.min(12,a.length-fc.n)}`};
const _RT4=R.teachers;R.teachers=(...a)=>{const v=_RT4(...a);v.after=fcDraw;v.html=v.html.replace('<div class="res"><b id="cnt"',`<div class="flv-w"><label class="fl" for="flv">Сложность</label><select class="f" id="flv"><option value="">Любая</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${lvl(n).name}</option>`).join('')}<option value="0">Ещё не оценён</option></select></div><div class="res"><b id="cnt"`).replace('Распределены по курсам. Сведения взяты с официальной страницы школы.','Уровень сложности складывается из отзывов студентов. Открой карточку, чтобы оценить преподавателя.');return v};
