/* ===================== v5: мероприятия из Telegram-каналов ВШБ ===================== */
let TG_EV=null;const EV_BG={bs_msu:'orange',vhsbcareer:'teal',msu_bs:'blue'};
const MON_G=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const tgEvCard=e=>{const d=parseD(e.date),soon=e.date===T0?'сегодня':Math.round((d-parseD(T0))/864e5)===1?'завтра':'';return `<article class="card ev"><div class="date bg-${EV_BG[e.ch]||'mustard'}"><b>${d.getDate()}</b><span>${MON_G[d.getMonth()]}</span></div><div class="body"><div class="tags"><span class="tag soon">${esc(e.chName)}${e.time?', '+esc(e.time):''}</span>${soon?`<span class="tag live">${soon}</span>`:''}</div><h3>${esc(e.title)}</h3>${e.text?`<p>${esc(e.text)}${e.text.length>=420?'…':''}</p>`:''}${(e.links||[]).length?`<p class="ev-ln small">${e.links.map(l=>{let h='';try{h=new URL(l).hostname.replace(/^www\./,'')}catch{}return h&&/^https:\/\//.test(l)?`<a class="tab" href="${esc(l)}" target="_blank" rel="noopener nofollow">${esc(h)} ↗</a>`:''}).join('')}</p>`:''}<p class="ev-src small"><a class="link" href="${esc(e.url)}" target="_blank" rel="noopener">Открыть пост в Telegram</a>${(e.src||[]).length>1?`<span class="muted">Тот же анонс: ${e.src.slice(1).map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.name)}</a>`).join(', ')}</span>`:''}</p></div></article>`};
const tgEvHtml=()=>!TG_EV?'<div class="card pad"><p class="muted">Загружаю анонсы из каналов…</p></div>':TG_EV.events.length?TG_EV.events.map(tgEvCard).join(''):'<div class="card pad"><p class="muted">В каналах сейчас нет анонсов с будущей датой.</p></div>';
async function loadTgEv(){await API_READY;if(!(API_ON&&window.API_H&&API_H.wiki>=4)){const b=$('#tgEv');if(b)b.closest('section').hidden=true;return}try{const r=await api('/api/events');if(r.ok||r.events.length)TG_EV=r;const b=$('#tgEv');if(b){if(TG_EV)b.innerHTML=tgEvHtml();else b.closest('section').hidden=true}}catch{const b=$('#tgEv');if(b&&!TG_EV)b.closest('section').hidden=true}}
const _REv5=R.events;R.events=(...a)=>{const v=_REv5(...a);v.html=v.html.replace('<div style="display:grid;gap:14px">',`<section class="sec" style="margin-top:0"><div class="sec-head"><h2 class="sec-t">Анонсы из каналов ВШБ</h2></div><p class="sec-sub">Собираются сами из каналов школы, студсовета и «Кузницы карьеры», обновляются каждые полчаса. Если один анонс вышел в нескольких каналах, здесь он один: главным считается канал, где больше подписчиков.</p><div id="tgEv" style="display:grid;gap:14px">${tgEvHtml()}</div></section><div class="sec-head"><h2 class="sec-t">С сайта школы</h2></div><div style="display:grid;gap:14px">`).replace('События школы в одной ленте.','Анонсы из Telegram-каналов школы и события с mgubs.ru.');const af=v.after;v.after=()=>{af&&af();loadTgEv()};return v};

/* ===================== v6: дедлайны из Moodle (edu.mgubs.ru) ===================== */
PERSONAL.add('moodle');
S.moodle=store.get('moodle',null)||{on:false,events:[]};
const _wlp6=wLoadPersonal;wLoadPersonal=function(){_wlp6.apply(this,arguments);S.moodle=store.get('moodle',null)||{on:false,events:[]}};
const mdOk=()=>API_ON&&apiTok()&&window.API_H&&API_H.wiki>=5;
const mdSubj=c=>{const n=norm(String(c||'').replace(/^[A-Za-zА-Яа-я]{2}\d{2}\s+/,''));return n.length<4?null:SUBJECTS.find(s=>{const m=norm(s.name);return m===n||n.includes(m)||m.includes(n)})||null};
const mdLocal=ms=>{const d=new Date(ms);if(d.getHours()===0&&d.getMinutes()===0)d.setMinutes(-1);return{d:iso(d),t:String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}};
const mdSet=m=>{S.moodle=m;store.set('moodle',m)};
/* дедлайны Moodle попадают в карточку «Дедлайны» нужного предмета */
dlOf=function(s){const md=(S.moodle.events||[]).filter(e=>{const x=mdSubj(e.course);return x&&x.id===s.id}).map(e=>{const l=mdLocal(e.at);return{t:e.title,d:l.d,tm:l.t,md:1}});return [...md,...(S.dl[s.id]||[]).map((x,k)=>({...x,own:1,k}))].sort((a,b)=>a.d<b.d?-1:1)};
function mdHtml(){const m=S.moodle,now=Date.now(),up=(m.events||[]).filter(e=>e.at>=now-864e5),gone=(m.events||[]).filter(e=>e.at<now-864e5).length;
 const row=e=>{const l=mdLocal(e.at),s=mdSubj(e.course),n=dDiff(T0,l.d);return `<li class="${e.at<now?'past':n<=2?'hot':''}"><span class="md-d"><b>${fmtD(l.d)}</b><small>${l.t}</small></span><span class="md-b"><b>${esc(e.title)}</b><small class="muted">${s?`<a href="/subject/${s.id}">${esc(s.name)}</a>`:esc(e.course||'')}${e.text?' · '+esc(e.text.slice(0,120)):''}</small></span><span class="md-w">${e.at<now?'прошло':dlWhen(l.d)}${e.link?`<a class="link" href="${esc(e.link)}" target="_blank" rel="noopener">В Moodle</a>`:''}</span></li>`};
 if(!m.on&&!(m.events||[]).length)return `<section class="card pad md" id="mdBox"><div class="pg-h"><h2>Дедлайны из Moodle</h2></div><p class="small muted">Сроки сдачи с edu.mgubs.ru подтянутся сами и появятся в карточках предметов. Пароль от Moodle не нужен.</p><ol class="md-how"><li>Зайди на edu.mgubs.ru → <b>Календарь</b> → <b>Экспорт календаря</b></li><li>Выбери «Все курсы» и «Последние и следующие 60 дней», нажми <b>Получить URL календаря</b></li><li>Скопируй ссылку и вставь сюда</li></ol><form class="wk-row" id="mdF" novalidate><input type="url" name="u" placeholder="https://edu.mgubs.ru/calendar/export_execute.php?…" aria-label="Ссылка на календарь Moodle"><button class="btn btn-o btn-sm">Подключить</button></form><p class="small muted">Или скачай там же файл .ics и <label class="link">загрузи его<input type="file" accept=".ics,text/calendar" class="vh" id="mdFile"></label>, но тогда новые сроки сами не подтянутся.</p>${mdOk()?'':'<p class="small muted">Подключение работает, когда сервер сайта включён.</p>'}</section>`;
 return `<section class="card pad md" id="mdBox"><div class="pg-h"><h2>Дедлайны из Moodle</h2><span class="md-a">${m.on?`<button class="link" data-mdre>Обновить</button>`:`<label class="link">Загрузить новый .ics<input type="file" accept=".ics,text/calendar" class="vh" id="mdFile"></label>`}<button class="link" data-mdoff>Отключить</button></span></div>${m.err?`<p class="small wk-pend">Не удалось обновить: ${esc(m.err)}. Показываю то, что загрузили ${m.at?fmtDT(m.at):'раньше'}.</p>`:m.at?`<p class="small muted">${m.on?'Обновляется само раз в час. ':''}Последнее обновление: ${fmtDT(m.at)}.</p>`:''}${up.length?`<ul class="md-l">${up.map(row).join('')}</ul>`:'<p class="muted">Ближайших сроков нет.</p>'}${gone?`<p class="small muted">Прошедших: ${gone}.</p>`:''}</section>`}
const mdRedraw=()=>{const b=$('#mdBox');if(b)b.outerHTML=mdHtml()};
async function mdLoad(){await API_READY;if(!mdOk())return;try{mdSet(await api('/api/moodle'));mdRedraw()}catch{}}
const _RAcc6=R.account;R.account=(...a)=>{const v=_RAcc6(...a);if(!S.auth||!v.html.includes('cb-ts'))return v;v.html=v.html.replace('<section class="sec"><div class="cb-ts">',`<section class="sec">${mdHtml()}</section><section class="sec"><div class="cb-ts">`);const af=v.after;v.after=()=>{af&&af();mdLoad()};return v};
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='mdF')return;e.preventDefault();const u=f.u.value.trim();if(!u){toast('Вставь ссылку из Moodle');f.u.focus();return}if(!mdOk()){toast('Сервер сайта сейчас выключен, попробуй позже');return}
 const b=$('button',f);b.disabled=true;b.textContent='Подключаю…';try{const r=await api('/api/moodle',{url:u});mdSet(r);mdRedraw();toast(r.err?`Ссылку сохранили, но Moodle не ответил: ${r.err}`:`Готово: ${plural((r.events||[]).length,'срок','срока','сроков')} из Moodle`);goal('moodle')}catch(x){toast(x.message);b.disabled=false;b.textContent='Подключить'}});
document.addEventListener('change',async e=>{if(e.target.id!=='mdFile'||!e.target.files.length)return;if(!mdOk()){toast('Сервер сайта сейчас выключен, попробуй позже');return}try{const ics=await e.target.files[0].text();const r=await api('/api/moodle/ics',{ics});mdSet({...r,on:S.moodle.on});mdRedraw();toast(`Загружено: ${plural((r.events||[]).length,'срок','срока','сроков')}`)}catch(x){toast(x.message)}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-mdre]')){try{const m=S.moodle;toast('Обновляю…');/* повторно отправляем сохранённую на сервере ссылку нельзя — просим GET с принудительным обновлением */const r=await api('/api/moodle?force=1');mdSet(r);mdRedraw();toast(r.err?r.err:'Обновлено')}catch(x){toast(x.message)}}
 if(e.target.closest('[data-mdoff]')){if(!confirm('Отключить Moodle? Сроки из него пропадут с сайта.'))return;try{if(mdOk())await api('/api/moodle',{url:''});mdSet({on:false,events:[]});mdRedraw();toast('Moodle отключён')}catch(x){toast(x.message)}}});

