 if(kind==='subject'){const title=f.title.value.trim(),sems=$$('[name=sem]:checked',f).map(x=>+x.value);if(title.length<3){toast('Напиши название предмета');f.title.focus();return}if(!sems.length){toast('Отметь хотя бы один семестр');return}if(SUBJECTS.some(s=>norm(s.name)===norm(title))){toast('Такой предмет уже есть в каталоге');return}
  key='subject:n-'+wUid();d={title,sems,control:f.control.value,req:f.req.value,isNew:true,about:'',breakdown:[],pass:0,teachers:[],topics:[],materials:[]};back='/subjects'}
