const wsFile=u=>u&&u.startsWith('/api/')?API+u:u;
const wsDemo=()=>{const h=n=>Date.now()+n*3600e3,me=wWho()||'ты';return{id:'demo',name:'Демо: исследование бренда',demo:true,done:false,deadline:defDl(18),rev:1,members:[{login:'anya',role:'lead'},{login:me,role:'member'},{login:'misha',role:'member'}],
 idea:'<p>Выясняем, как студенты ВШБ выбирают кофейню рядом с корпусом, и даём рекомендации бренду.</p><p><b>Результат:</b> отчёт на 15 страниц и презентация на защиту.</p>',
 tasks:[{id:'d1',t:'Собрать вторичные данные',col:'done',who:'anya',s:h(-200),e:h(-80),n:'',color:'mint',subs:[{t:'Отчёты рынка',done:true},{t:'Конкуренты',done:true}]},{id:'d2',t:'Гайд интервью',col:'done',who:me,s:h(-120),e:h(-30),n:'',color:'',subs:[]},{id:'d3',t:'Провести 8 интервью',col:'doing',who:'misha',s:h(-40),e:h(90),n:'Двое респондентов перенесли на четверг',color:'peach',subs:[{t:'Найти респондентов',done:true},{t:'Записать 8 интервью',done:false},{t:'Расшифровать',done:false}]},{id:'d4',t:'Опрос в Google Forms',col:'doing',who:me,s:h(-10),e:h(140),n:'',color:'blue',subs:[]},{id:'d5',t:'Собрать отчёт',col:'todo',who:'anya',s:h(150),e:h(330),n:'',color:'',subs:[]},{id:'d6',t:'Презентация на защиту',col:'todo',who:'',s:h(300),e:h(420),n:'',color:'yellow',subs:[]}],
 notes:[{id:'n1',title:'Отчёт сдаём на английском',body:'<p>Проверить термины по глоссарию курса.</p>',type:'Решение',color:'yellow',who:'',by:'anya',at:h(-50)},{id:'n2',title:'Вопрос к руководителю',body:'<p>Можно ли включать респондентов не из ВШБ?</p>',type:'Вопрос',color:'blue',who:'anya',by:me,at:h(-20)},{id:'n3',title:'Идея для слайда',body:'<p>Карта пути клиента от пары до кофе: <b>3 точки контакта</b>.</p>',type:'Идея',color:'mint',who:'',by:'misha',at:h(-5)}],
 chat:[{id:'c1',by:'anya',text:'Привет! Разбираем задачи на этой неделе?',at:h(-30)},{id:'c2',by:'misha',text:'Интервью беру на себя, два уже назначил.',at:h(-29)},{id:'c3',by:me,text:'Я делаю опрос, к пятнице пришлю ссылку.',at:h(-28)}],
 mats:[{id:'m1',name:'Требования к проекту',url:'https://latisha.ru/',by:'anya',at:h(-200)}]}};
async function wsOp(op,body,quiet){if(WS.demo){toast('Это демо-проект, в нём ничего не меняется. Создай свой проект.');return false}
 try{const r=await api(`/api/projects/${WS.p.id}/op`,{op,...(body||{})});if(r.gone){toast(op==='delete'?'Проект удалён':'Ты вышел из проекта');LOC.hash='/projects';return true}WS.p=r.project;if(!quiet)wsDraw();return true}catch(x){toast(x.message);return false}}
/* ---------- список ---------- */
const _RPold=R.projects;
R.projects=()=>{if(!has('tracker'))return{title:`Проекты команды — ${D.brand}`,html:`<div class="wrap ws"><div class="phead"><h1 tabindex="-1">Проекты</h1><p class="d">Общая доска для команды: канбан, Гант, заметки и чат.</p></div><div class="card pad" style="margin-bottom:14px"><p><b>Создавать свои проекты можно с тарифа за ${rub(D.access.tracker)}.</b></p><p class="muted">Участвовать в чужих можно бесплатно: когда лидер добавит тебя по логину, проект появится ниже.</p><a class="btn btn-o btn-sm" href="/pricing">Посмотреть тарифы</a></div><div id="wsList"><div class="card pad"><p class="muted">Загружаю проекты…</p></div></div></div>`,after:wsLoadList};return{title:`Проекты команды: канбан, Гант, заметки, чат — ${D.brand}`,html:`<div class="wrap ws"><div class="phead ph-row"><div><h1 tabindex="-1">Проекты</h1><p class="d">Общая доска для команды: задачи, сроки, заметки и чат. Лидер создаёт проект и добавляет участников по логину.</p></div><button type="button" class="btn btn-o" data-wsnew>+ Создать проект</button></div><div id="wsNew"></div><div id="wsList"><div class="card pad"><p class="muted">Загружаю проекты…</p></div></div></div>`,after:wsLoadList}};
const wsCard=x=>`<a class="card pad ws-pc ${x.done?'fin':''}" href="/project/${x.id}"><div class="ws-pch"><b>${esc(x.name)}</b>${x.demo?'<span class="tag soon">Демо</span>':x.done?'<span class="tag">Закончен</span>':`<span class="tag ${x.role==='lead'?'live':''}">${x.role==='lead'?'Ты лидер':'Участник'}</span>`}</div><p class="small muted">${x.deadline?`Срок: ${fmtDT(x.deadline)}, ${leftTxt(x.deadline)}`:'Срок не задан'} · ${plural(x.members,'участник','участника','участников')}</p><div class="prog"><i style="width:${x.tasks?Math.round(x.tasksDone/x.tasks*100):0}%"></i></div><p class="small">${x.tasks?`Готово ${x.tasksDone} из ${x.tasks}`:'Задач пока нет'}</p></a>`;
async function wsLoadList(){const box=$('#wsList');if(!box)return;await API_READY;const d=wsDemo(),demo=wsCard({...d,members:d.members.length,tasks:d.tasks.length,tasksDone:d.tasks.filter(t=>t.col==='done').length});
 if(!wsOk()){box.innerHTML=`<div class="card pad"><p>${apiTok()||!API_ON?'Проекты хранятся на сервере, а он сейчас не отвечает. Попробуй позже.':'Чтобы создавать проекты, войди в аккаунт.'}</p></div><div class="ws-grid" style="margin-top:14px">${demo}</div>`;return}
 try{const {projects}=await api('/api/projects');box.innerHTML=`${projects.length||!has('tracker')?'':'<div class="card pad"><p>У тебя пока нет проектов. Создай свой или попроси лидера команды добавить тебя по логину. Ниже демо, чтобы посмотреть, как всё устроено.</p></div>'}<div class="ws-grid" style="margin-top:${projects.length?0:14}px">${projects.map(wsCard).join('')}${demo}</div>`}catch(x){box.innerHTML=`<div class="card pad"><p>${esc(x.message)}</p></div>`}}
document.addEventListener('click',e=>{if(!e.target.closest('[data-wsnew]'))return;const b=$('#wsNew');if(!b)return;if(!wsOk()){toast('Сервер сейчас не отвечает, проект создать не получится');return}b.innerHTML=`<form class="card pad ws-nf" id="wsNF" novalidate><h2>Новый проект</h2><div class="wk-row"><label class="fl" style="flex:2;min-width:220px">Название<input type="text" name="name" maxlength="100" placeholder="Например, Исследование бренда"></label><label class="fl" style="flex:1;min-width:200px">Срок сдачи<input type="datetime-local" name="dl" value="${dtv(defDl(14))}"></label></div><div class="wk-row"><button class="btn btn-o btn-sm">Создать</button><button type="button" class="btn btn-oo btn-sm" data-wsnewx>Отмена</button></div></form>`;b.querySelector('input').focus()});
document.addEventListener('click',e=>{if(e.target.closest('[data-wsnewx]'))$('#wsNew').innerHTML=''});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='wsNF')return;e.preventDefault();const name=f.name.value.trim();if(name.length<2){toast('Напиши название проекта');f.name.focus();return}try{const r=await api('/api/projects',{name,deadline:dtms(f.dl.value)});goal('project_new');LOC.hash='/project/'+r.project.id}catch(x){toast(x.message)}});
/* ---------- страница проекта ---------- */
const _RPrOld=R.project;
R.project=(p,id)=>{if(['board','gantt','notes','chat','info'].includes(p.v))WS.tab=p.v;const same=WS.p&&WS.p.id===id;if(!same){WS.p=null;if(!p.v)WS.tab='board'}WS.demo=id==='demo';
 return{title:`Проект — ${D.brand}`,html:`<div class="wrap ws" data-ws="${esc(id)}"><div id="wsBody">${same?wsHtml():'<div class="card pad"><p class="muted">Загружаю проект…</p></div>'}</div></div>`,after:async()=>{if(WS.demo){if(!same)WS.p=wsDemo();wsDraw();return}await API_READY;if(!wsOk()){$('#wsBody').innerHTML='<div class="card pad"><p>Проект хранится на сервере, а он сейчас не отвечает. Попробуй позже.</p><a class="btn btn-oo btn-sm" href="/projects">К списку проектов</a></div>';return}try{WS.p=(await api('/api/projects/'+id)).project;wsDraw()}catch(x){$('#wsBody').innerHTML=`<div class="card pad"><p>${esc(x.message)}</p><a class="btn btn-oo btn-sm" href="/projects">К списку проектов</a></div>`}}}};
function wsDraw(){const b=$('#wsBody');if(!b||!WS.p)return;document.title=`${WS.p.name} — ${D.brand}`;const draft=$('#wsMsg')?$('#wsMsg').value:'';b.innerHTML=wsHtml();if(WS.tab==='chat'){const l=$('#wsChatL');l.scrollTop=l.scrollHeight;const i=$('#wsMsg');if(i&&draft){i.value=draft;i.focus()}}}
function wsHtml(){const p=WS.p,lead=wsLead(),dn=p.tasks.filter(t=>t.col==='done').length;
 return `<nav class="crumbs small"><a href="/projects">Проекты</a> / ${esc(p.name)}</nav><header class="ws-h"><div><h1 tabindex="-1">${esc(p.name)}</h1><div class="tags">${p.demo?'<span class="tag soon">Демо: ничего не сохраняется</span>':''}${p.done?'<span class="tag">Проект закончен</span>':''}<span class="tag ${p.deadline&&p.deadline-Date.now()<3*864e5&&!p.done?'bad':''}">${p.deadline?`Срок: ${fmtDT(p.deadline)} · ${leftTxt(p.deadline)}`:'Срок не задан'}</span><span class="tag">Готово ${dn} из ${p.tasks.length}</span></div><div class="ws-mem">${p.members.map(m=>`<span class="ws-av ${m.role==='lead'?'lead':''}" title="${m.role==='lead'?'Лидер':'Участник'}">${esc(wsName(m.login))}${m.role==='lead'?' ★':''}</span>`).join('')}</div></div>
 <div class="ws-act">${lead?`<button type="button" class="btn btn-oo btn-sm" data-wsfin="${p.done?0:1}">${p.done?'Открыть снова':'Закончить проект'}</button><button type="button" class="btn btn-oo btn-sm au-bad" data-wsdel>Удалить проект</button>`:`<button type="button" class="btn btn-oo btn-sm au-bad" data-wsleave>Выйти из проекта</button>`}</div></header>
 <div class="ws-tabs" role="tablist">${[['board','Канбан'],['gantt','Гант'],['notes',`Заметки${p.notes.length?` · ${p.notes.length}`:''}`],['chat',`Чат${p.chat.length?` · ${p.chat.length}`:''}`],['info','О проекте']].map(([k,l])=>`<button type="button" class="tab" role="tab" data-wstab="${k}" aria-selected="${WS.tab===k}">${l}</button>`).join('')}</div>
 <div id="wsTab">${{board:wsBoard,gantt:wsGantt,notes:wsNotes,chat:wsChat,info:wsInfo}[WS.tab]()}</div>`}
const _RPr5=R.projects;R.projects=(...a)=>{const v=_RPr5(...a);if(S.auth&&v.html){v.html=v.html.replace('<div class="wrap ws">','<div class="wrap ws">'+cabNav('proj',''));const af=v.after;v.after=()=>{af&&af();cabCounts()}}return v};
/* канбан */
const wsAuto=id=>{let h=0;for(const c of String(id))h=(h*31+c.charCodeAt(0))>>>0;return WS_CLR[h%WS_CLR.length][0]};
const wsTaskCard=t=>{const sd=(t.subs||[]).filter(s=>s.done).length,late=t.e&&t.e<Date.now()&&t.col!=='done',i=WS_COLS.findIndex(c=>c[0]===t.col);
 return `<article class="ws-c c-${t.color||wsAuto(t.id)}" draggable="true" data-wst="${t.id}" tabindex="0" role="button" aria-label="${esc(t.t)}, открыть"><b>${esc(t.t)}</b><div class="ws-cm">${t.who?`<span class="ws-av sm">${esc(wsName(t.who))}</span>`:''}${t.e?`<span class="${late?'late':''}">${fmtDT(t.e)}</span>`:''}${(t.subs||[]).length?`<span>☑ ${sd}/${t.subs.length}</span>`:''}</div>${(t.subs||[]).length?`<div class="prog sm"><i style="width:${sd/t.subs.length*100}%"></i></div>`:''}<div class="ws-mv">${i>0?`<button type="button" class="ib" data-wsmv="${t.id}|${WS_COLS[i-1][0]}" aria-label="В «${WS_COLS[i-1][1]}»">←</button>`:'<span></span>'}${i<2?`<button type="button" class="ib" data-wsmv="${t.id}|${WS_COLS[i+1][0]}" aria-label="В «${WS_COLS[i+1][1]}»">→</button>`:''}</div></article>`};
function wsBoard(){const p=WS.p;return `<div class="ws-board">${WS_COLS.map(([k,l])=>{const a=p.tasks.filter(t=>t.col===k).sort((x,y)=>(x.e||9e15)-(y.e||9e15));return `<section class="ws-col k-${k}" data-wscol="${k}"><div class="ws-colh"><i class="ws-dot"></i><b>${l}</b><span class="muted">${a.length}</span><button type="button" class="ib" data-wsadd="${k}" aria-label="Добавить задачу в «${l}»">+</button></div>${a.map(wsTaskCard).join('')||'<p class="small muted ws-e">Пусто. Перетащи сюда задачу или нажми +</p>'}</section>`}).join('')}</div>`}
/* Гант */
function wsGantt(){const p=WS.p,now=Date.now(),a=p.tasks.filter(t=>t.e).map(t=>({...t,s:t.s&&t.s<t.e?t.s:t.e-864e5})).sort((x,y)=>x.s-y.s||x.e-y.e);if(!a.length)return '<div class="card pad"><p class="muted">На диаграмме появляются задачи со сроком. Открой задачу на канбане и поставь дату.</p></div>';
 const d0=new Date(Math.min(...a.map(t=>t.s),now));d0.setHours(0,0,0,0);const d1=new Date(Math.max(...a.map(t=>t.e),p.deadline||0,now));d1.setHours(24,0,0,0);
 const lo=d0.getTime(),hi=d1.getTime(),W=hi-lo,pc=ms=>+(((ms-lo)/W)*100).toFixed(3),days=Math.round(W/864e5),step=days<=14?1:days<=31?2:days<=70?7:14,dw=100/days;let grid='',ticks='';
 for(let i=0;i<days;i++){const d=new Date(lo);d.setDate(d.getDate()+i);const wd=d.getDay();if(wd===0||wd===6)grid+=`<i class="gx-we" style="left:${(i*dw).toFixed(3)}%;width:${dw.toFixed(3)}%"></i>`;if(i%step===0){grid+=`<i class="gx-ln" style="left:${(i*dw).toFixed(3)}%"></i>`;ticks+=`<span style="left:${(i*dw).toFixed(3)}%">${d.getDate()}${i===0||d.getDate()<=step?' '+MON[d.getMonth()]:''}</span>`}}
 const mark=(ms,cls,txt)=>{const x=pc(ms);return `<i class="gx-m ${cls}" style="left:${x}%"><em class="${x>78?'r':''}">${txt}</em></i>`};
 const row=t=>{const st=t.col==='done'?'ok':t.col==='doing'?'go':'to',late=t.col!=='done'&&t.e<now,x0=pc(t.s),x1=pc(t.e),lab=`${t.col==='done'?'✓ ':''}${t.who?esc(wsName(t.who))+' · ':''}${late?'просрочено':'до '+fmtD(iso(new Date(t.e)))}`;
  return `<div class="gx-r"><button type="button" class="gx-n" data-wst="${t.id}" title="${esc(t.t)}">${esc(t.t)}</button><div class="gx-tr"><button type="button" class="gx-b s-${st}${late?' late':''}" style="left:${x0}%;width:max(12px,${(x1-x0).toFixed(3)}%)" data-wst="${t.id}" aria-label="${esc(t.t)}: до ${fmtDT(t.e)}"></button><span class="gx-t${late?' late':''}" style="${x1>70?`right:${(100-x0).toFixed(3)}%;padding-right:8px`:`left:${x1}%;padding-left:8px`}">${lab}</span></div></div>`};
 return `<div class="card pad gx"><div class="gx-in"><div class="gx-ov">${grid}${mark(now,'now','Сегодня, '+fmtD(iso(new Date(now))))}${p.deadline?mark(p.deadline,'dl','Срок проекта, '+fmtD(iso(new Date(p.deadline)))):''}</div><div class="gx-r gx-hd"><span></span><div class="gx-tr gx-tk">${ticks}</div></div>${a.map(row).join('')}</div><p class="small muted gx-lg"><span><i class="gx-sw s-to"></i>нужно сделать</span><span><i class="gx-sw s-go"></i>в работе</span><span><i class="gx-sw s-ok"></i>готово</span><span>Нажми на полосу или название, чтобы открыть задачу.</span></p></div>`}
/* заметки */
function wsNotes(){const p=WS.p;return `<div class="ws-nb"><button type="button" class="btn btn-o btn-sm" data-wsnote="new">+ Заметка</button></div>${p.notes.length?`<div class="ws-notes">${p.notes.map(n=>`<article class="ws-n c-${n.color||'yellow'}" data-wsnote="${n.id}" tabindex="0" role="button"><div class="ws-nh"><span class="tag">${esc(n.type||'Заметка')}</span>${n.who?`<span class="ws-av sm">для: ${esc(wsName(n.who))}</span>`:''}</div>${n.title?`<h3>${esc(n.title)}</h3>`:''}<div class="ws-nbody">${wShow(n.body)}</div><footer class="small muted">${esc(wsName(n.by))} · ${fmtDT(n.at)}</footer></article>`).join('')}</div>`:'<div class="card pad"><p class="muted">Заметок пока нет. Сюда удобно класть решения команды, идеи, вопросы к руководителю и фото с пар.</p></div>'}`}
/* чат */
const wsMsgs=()=>{const p=WS.p,me=wWho();let day='';return p.chat.length?p.chat.map(m=>{const d=fmtD(iso(new Date(m.at))),sep=d!==day?`<div class="ws-day">${d}</div>`:'';day=d;const t=new Date(m.at);return `${sep}<div class="ws-m ${m.by===me?'me':''}"><div class="ws-mb">${m.by===me?'':`<b>${esc(m.by)}</b>`}<p>${esc(m.text).replace(/(https:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>').replace(/\n/g,'<br>')}</p><small>${z2(t.getHours())}:${z2(t.getMinutes())}</small></div></div>`}).join(''):'<p class="muted small ws-e">Сообщений пока нет. Напиши первым.</p>'};
function wsChat(){return `<div class="card ws-chat"><div class="ws-chl" id="wsChatL" aria-live="polite">${wsMsgs()}</div><form class="ws-chf" id="wsChF"><textarea id="wsMsg" rows="1" maxlength="2000" placeholder="Сообщение команде. Enter — отправить, Shift+Enter — новая строка" aria-label="Сообщение"></textarea><button class="btn btn-o btn-sm">Отправить</button></form></div>`}
/* о проекте */
function wsInfo(){const p=WS.p,lead=wsLead();return `<div class="ws-info"><div class="stack"><section class="card pad"><div class="pg-h"><h2>Идея проекта</h2>${lead?'<button type="button" class="link" data-wsmeta>Править</button>':''}</div>${p.idea&&wText(p.idea)?wShow(p.idea):`<p class="muted">Описания пока нет.${lead?' Напиши в двух абзацах, что делаем и какой результат сдаём.':''}</p>`}</section>
 <section class="card pad"><h2>Материалы</h2>${p.mats.length?`<ul class="ws-ml">${p.mats.map(m=>`<li><a href="${esc(wsFile(m.url))}" target="_blank" rel="noopener">${m.url.startsWith('/api/')?'📎':'🔗'} ${esc(m.name)}</a><small class="muted">${esc(wsName(m.by))}${m.size?' · '+fmtSize(m.size):''}</small><button type="button" class="ib" data-wsmatx="${m.id}" aria-label="Убрать материал">${I.x}</button></li>`).join('')}</ul>`:'<p class="muted">Здесь лежат требования, шаблоны, данные и ссылки.</p>'}<form class="wk-row ws-mf" id="wsMatF" novalidate><input type="text" name="name" maxlength="140" placeholder="Название" aria-label="Название"><input type="url" name="url" placeholder="https://…" aria-label="Ссылка"><button class="btn btn-oo btn-sm">Добавить ссылку</button><label class="btn btn-oo btn-sm rg-file">📎 Файл<input type="file" class="vh" id="wsMatFile" multiple></label></form></section></div>
 <aside class="stack"><section class="card pad"><h2>Команда</h2><ul class="ws-tl">${p.members.map(m=>`<li><span><b>${esc(wsName(m.login))}</b><small class="muted">${m.role==='lead'?'Лидер':'Участник'}</small></span>${lead&&m.role!=='lead'?`<span><button type="button" class="link" data-wslead="${esc(m.login)}">Сделать лидером</button><button type="button" class="ib" data-wsmemx="${esc(m.login)}" aria-label="Убрать ${esc(m.login)} из проекта">${I.x}</button></span>`:''}</li>`).join('')}</ul>${lead?`<form class="wk-row" id="wsMemF" novalidate><div class="dm-cb pp-cb"><input type="text" name="login" maxlength="40" placeholder="Начни вводить логин" aria-label="Логин участника" autocomplete="off" data-people="${esc(p.members.map(m=>m.login).join(','))}" role="combobox" aria-expanded="false" aria-autocomplete="list"><div class="dm-sug pp-sug" role="listbox" hidden></div></div><button class="btn btn-o btn-sm">Добавить</button></form><p class="small muted">Участник должен быть зарегистрирован на сайте. Бот напишет ему, что его добавили.</p>`:''}</section></aside></div>`}
/* ---------- диалоги ---------- */
function wsOv(html){wsOvX();const o=document.createElement('div');o.className='ws-ov';o.innerHTML=`<div class="ws-dlg" role="dialog" aria-modal="true"><button type="button" class="ib ws-x" data-wsx aria-label="Закрыть">${I.x}</button>${html}</div>`;document.body.append(o);wsOv.back=document.activeElement;const i=o.querySelector('input,textarea,[contenteditable]');i&&i.focus();return o}
function wsOvX(){const o=$('.ws-ov');if(o){o.remove();wsOv.back&&wsOv.back.isConnected&&wsOv.back.focus()}}
const clrPick=(cur,none)=>`<div class="ws-clr">${(none?[['','Цвет подберётся сам']]:[]).concat(WS_CLR).map(([k,l])=>`<label title="${l}"><input type="radio" name="color" value="${k}" class="vh" ${k===(cur||(none?'':'yellow'))?'checked':''}><span class="c-${k||'none'}" aria-label="${l}"></span></label>`).join('')}</div>`;
const memSel=(name,cur,all)=>`<select class="f" name="${name}"><option value="">${all}</option>${WS.p.members.map(m=>`<option value="${esc(m.login)}" ${m.login===cur?'selected':''}>${esc(wsName(m.login))}</option>`).join('')}</select>`;
const subRow=s=>`<div class="ws-sr"><input type="checkbox" ${s.done?'checked':''} aria-label="Готово"><input type="text" value="${esc(s.t||'')}" maxlength="160" placeholder="Подпункт" aria-label="Подпункт"><button type="button" class="ib" data-wssubx aria-label="Удалить подпункт">${I.x}</button></div>`;
function wsTaskDlg(id,col){const t=id?WS.p.tasks.find(x=>x.id===id):{col:col||'todo',who:'',s:Date.now(),e:defDl(7),subs:[],color:''};if(!t)return;
 wsOv(`<form id="wsTF" data-id="${id||''}" novalidate><h2>${id?'Задача':'Новая задача'}</h2><label class="fl">Название<input type="text" name="t" value="${esc(t.t||'')}" maxlength="160"></label><div class="ws-2"><label class="fl">Статус<select class="f" name="col">${WS_COLS.map(([k,l])=>`<option value="${k}" ${k===t.col?'selected':''}>${l}</option>`).join('')}</select></label><label class="fl">Исполнитель${memSel('who',t.who,'Не назначен')}</label><label class="fl">Начало<input type="datetime-local" name="s" value="${dtv(t.s)}"></label><label class="fl">Срок<input type="datetime-local" name="e" value="${dtv(t.e)}"></label></div><span class="fl">Цвет карточки</span>${clrPick(t.color,true)}<fieldset class="ws-subs"><legend class="fl">Подпункты</legend><div id="wsSubs">${(t.subs||[]).map(subRow).join('')}</div><button type="button" class="link" data-wssubadd>+ Добавить подпункт</button></fieldset><label class="fl">Заметка<textarea name="n" rows="3" maxlength="4000" placeholder="Что важно помнить по этой задаче">${esc(t.n||'')}</textarea></label><div class="ws-df">${id?'<button type="button" class="link wk-del" data-wstdel>Удалить задачу</button>':'<span></span>'}<button class="btn btn-o btn-sm">Сохранить</button></div></form>`)}
function wsNoteDlg(id){const n=id&&id!=='new'?WS.p.notes.find(x=>x.id===id):{color:'yellow',type:'Заметка',who:'',body:''};if(!n)return;const can=!n.id||n.by===wWho()||wsLead();
 wsOv(`<form id="wsNoF" data-id="${n.id||''}" novalidate class="ws-nd"><h2>${n.id?'Заметка':'Новая заметка'}</h2><label class="fl">Заголовок<input type="text" name="title" value="${esc(n.title||'')}" maxlength="140"></label><div class="ws-2"><label class="fl">Тип<select class="f" name="type">${WS_NT.map(x=>`<option ${x===n.type?'selected':''}>${x}</option>`).join('')}</select></label><label class="fl">К кому относится${memSel('who',n.who,'Ко всей команде')}</label></div><span class="fl">Цвет листочка</span>${clrPick(n.color,false)}<span class="fl">Текст</span>${teHtml('wsn',n.body||'','Текст заметки. Фото можно вставить через Ctrl+V или перетащить')}<div class="ws-df">${n.id&&can?'<button type="button" class="link wk-del" data-wsndel>Удалить заметку</button>':'<span></span>'}<button class="btn btn-o btn-sm">Сохранить</button></div></form>`)}
/* ---------- события ---------- */
document.addEventListener('click',async e=>{const q=s=>e.target.closest(s);let b;
 if(q('[data-wsx]')||(e.target.classList&&e.target.classList.contains('ws-ov'))){wsOvX();return}
 if(!$('[data-ws]'))return;
 if(b=q('[data-wstab]')){WS.tab=b.dataset.wstab;history.replaceState(null,'',location.pathname+'?v='+WS.tab);wsDraw();return}
 if(b=q('[data-wsmv]')){e.stopPropagation();const [id,col]=b.dataset.wsmv.split('|');wsOp('task_move',{id,col});return}
 if(b=q('[data-wsadd]')){if(WS.demo){wsOp();return}wsTaskDlg(null,b.dataset.wsadd);return}
 if(q('[data-wssubadd]')){$('#wsSubs').insertAdjacentHTML('beforeend',subRow({}));$('#wsSubs .ws-sr:last-child input[type=text]').focus();return}
 if(b=q('[data-wssubx]')){b.closest('.ws-sr').remove();return}
 if(q('[data-wstdel]')){const id=$('#wsTF').dataset.id;if(confirm('Удалить задачу?')){wsOvX();wsOp('task_del',{id})}return}
 if(q('[data-wsndel]')){const id=$('#wsNoF').dataset.id;if(confirm('Удалить заметку?')){wsOvX();wsOp('note_del',{id})}return}
 if((b=q('[data-wst]'))&&!q('.ws-ov')){wsTaskDlg(b.dataset.wst);return}
 if((b=q('[data-wsnote]'))&&!q('.ws-ov')){if(b.dataset.wsnote==='new'&&WS.demo){wsOp();return}wsNoteDlg(b.dataset.wsnote);return}
 if(b=q('[data-wsfin]')){const on=b.dataset.wsfin==='1';if(!on||confirm('Закончить проект? Доска закроется для изменений, чат останется. Открыть снова можно в любой момент.'))wsOp('finish',{on});return}
 if(q('[data-wsdel]')){if(confirm(`Удалить проект «${WS.p.name}» со всеми задачами, заметками и чатом? Вернуть его будет нельзя.`))wsOp('delete');return}
 if(q('[data-wsleave]')){if(confirm('Выйти из проекта? Твои задачи останутся без исполнителя. Вернуть тебя сможет только лидер.'))wsOp('leave');return}
 if(b=q('[data-wsmatx]')){wsOp('mat_del',{id:b.dataset.wsmatx});return}
 if(b=q('[data-wsmemx]')){if(confirm(`Убрать ${b.dataset.wsmemx} из проекта?`))wsOp('member_del',{login:b.dataset.wsmemx});return}
 if(b=q('[data-wslead]')){if(confirm(`Передать лидерство ${b.dataset.wslead}? Ты станешь обычным участником.`))wsOp('lead',{login:b.dataset.wslead});return}
 if(q('[data-wsmeta]')){const p=WS.p;wsOv(`<form id="wsMF" novalidate class="ws-nd"><h2>О проекте</h2><label class="fl">Название<input type="text" name="name" value="${esc(p.name)}" maxlength="100"></label><label class="fl" style="max-width:260px">Срок сдачи<input type="datetime-local" name="dl" value="${dtv(p.deadline)}"></label><span class="fl">Идея проекта</span>${teHtml('wsi',p.idea||'','Что делаем, для кого и какой результат сдаём')}<div class="ws-df"><span></span><button class="btn btn-o btn-sm">Сохранить</button></div></form>`);return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.ws-ov')){wsOvX();return}if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='wsMsg'){e.preventDefault();$('#wsChF').requestSubmit();return}if(e.key==='Enter'&&e.target.matches&&e.target.matches('.ws-c,.ws-n')){e.target.click()}});
document.addEventListener('submit',async e=>{const f=e.target;
 if(f.id==='wsTF'){e.preventDefault();const t={id:f.dataset.id||undefined,t:f.t.value.trim(),col:f.col.value,who:f.who.value,s:dtms(f.s.value),e:dtms(f.e.value),n:f.n.value,color:(f.querySelector('[name=color]:checked')||{}).value||'',subs:$$('.ws-sr',f).map(r=>({t:r.querySelector('input[type=text]').value.trim(),done:r.querySelector('input[type=checkbox]').checked})).filter(x=>x.t)};if(!t.t){toast('Напиши название задачи');f.t.focus();return}if(t.s&&t.e&&t.s>t.e){toast('Начало позже срока: поправь даты');return}if(WS.demo){wsOp();return}wsOvX();wsOp('task_save',{task:t})}
 if(f.id==='wsNoF'){e.preventDefault();const n={id:f.dataset.id||undefined,title:f.title.value.trim(),type:f.type.value,who:f.who.value,color:(f.querySelector('[name=color]:checked')||{}).value||'yellow',body:teGet('wsn')};if(!n.title&&!wText(n.body)&&!/<img/.test(n.body)){toast('Напиши заголовок или текст');return}if(WS.demo){wsOp();return}wsOvX();wsOp('note_save',{note:n})}
 if(f.id==='wsMF'){e.preventDefault();const name=f.name.value.trim();if(name.length<2){toast('Название слишком короткое');return}const idea=teGet('wsi');wsOvX();wsOp('meta',{name,deadline:dtms(f.dl.value),idea})}
 if(f.id==='wsChF'){e.preventDefault();const i=$('#wsMsg'),t=i.value.trim();if(!t)return;i.value='';i.style.height='';if(!(await wsOp('chat',{text:t},true))){i.value=t;return}const l=$('#wsChatL');if(l){l.innerHTML=wsMsgs();l.scrollTop=l.scrollHeight}const tb=$('.ws-tabs [aria-selected=true] span,.ws-tabs .on span');i.focus({preventScroll:true})}
 if(f.id==='wsMatF'){e.preventDefault();const url=f.url.value.trim();if(!/^https:\/\//.test(url)){toast('Ссылка должна начинаться с https://');f.url.focus();return}wsOp('mat_add',{name:f.name.value.trim(),url})}
 if(f.id==='wsMemF'){e.preventDefault();const l=f.login.value.trim();if(!l){f.login.focus();return}if(await wsOp('member_add',{login:l}))toast('Участник добавлен')}});
document.addEventListener('change',async e=>{if(e.target.id!=='wsMatFile'||!e.target.files.length)return;if(WS.demo){wsOp();return}for(const f of e.target.files){try{toast(`Загружаю «${f.name}»…`);const r=await WB.upload(f);await wsOp('mat_add',{name:r.name||f.name,url:r.url.replace(API,''),size:r.size||f.size})}catch(x){toast(x.message)}}});
/* перетаскивание карточек */
document.addEventListener('dragstart',e=>{const c=e.target.closest&&e.target.closest('.ws-c');if(c){WS.drag=c.dataset.wst;e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',WS.drag)}catch{}c.classList.add('drag')}});
document.addEventListener('dragend',()=>{WS.drag=null;$$('.ws-c.drag').forEach(c=>c.classList.remove('drag'));$$('.ws-col.over').forEach(c=>c.classList.remove('over'))});
document.addEventListener('dragover',e=>{const c=WS.drag&&e.target.closest&&e.target.closest('.ws-col');if(c){e.preventDefault();$$('.ws-col.over').forEach(x=>x!==c&&x.classList.remove('over'));c.classList.add('over')}});
document.addEventListener('drop',e=>{const c=WS.drag&&e.target.closest&&e.target.closest('.ws-col');if(!c)return;e.preventDefault();const id=WS.drag,t=WS.p.tasks.find(x=>x.id===id);WS.drag=null;if(t&&t.col!==c.dataset.wscol)wsOp('task_move',{id,col:c.dataset.wscol})});
/* обновление у всех участников: раз в 6 секунд, пока открыт проект */
setInterval(async()=>{const w=$('[data-ws]');if(!w||WS.demo||!WS.p||document.hidden||$('.ws-ov')||WS.drag||!wsOk())return;try{const r=await api(`/api/projects/${WS.p.id}?rev=${WS.p.rev}`);if(r.same||!r.project||!$('[data-ws]'))return;WS.p=r.project;const a=document.activeElement;if(WS.tab==='chat'){const l=$('#wsChatL'),bottom=l.scrollHeight-l.scrollTop-l.clientHeight<60;l.innerHTML=wsMsgs();if(bottom)l.scrollTop=l.scrollHeight}else if(!(a&&a.closest&&a.closest('#wsTab')&&/INPUT|TEXTAREA/.test(a.tagName)))wsDraw()}catch(x){if(x.status===404){toast('Проект удалён или тебя из него убрали');LOC.hash='/projects'}}},6000);

/* ===================== расписание студента ===================== */
S.sched=store.get('sched',null)||[];
const _wlpS=wLoadPersonal;wLoadPersonal=function(){_wlpS.apply(this,arguments);S.sched=store.get('sched',null)||[]};
const WD_S=['','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'];
const tMin=t=>{const [h,m]=String(t||'0:0').split(':').map(Number);return (h||0)*60+(m||0)},tStr=m=>z2(Math.floor(Math.max(0,Math.min(1439,m))/60))+':'+z2(Math.max(0,Math.min(1439,m))%60);
const schedEnd=x=>x.end&&tMin(x.end)>tMin(x.time)?x.end:tStr(tMin(x.time)+90);
const schedDay=d=>S.sched.filter(x=>x.day===d).sort((a,b)=>a.time<b.time?-1:1);
const schedSpan=a=>a.length?`${plural(a.length,'пара','пары','пар')} · ${a[0].time}–${a.map(schedEnd).sort().pop()}`:'';
const durTxt=m=>m>=60?`${Math.floor(m/60)} ч${m%60?' '+m%60+' мин':''}`:`${m} мин`;
const schedNowMin=()=>{const d=new Date();return d.getHours()*60+d.getMinutes()};
const schedRow=(x,ed,live)=>{const s=SUBJECTS.find(k=>norm(k.name)===norm(x.title)),on=live&&tMin(x.time)<=schedNowMin()&&schedNowMin()<tMin(schedEnd(x));return `<li class="${on?'on':''}"><span class="sc-t"><b>${esc(x.time)}</b><i>${esc(schedEnd(x))}</i></span><span><b>${s?`<a href="/subject/${s.id}">${esc(x.title)}</a>`:esc(x.title)}${on?' <span class="tag live">идёт сейчас</span>':''}</b><small class="muted">${[x.kind,x.room?'ауд. '+x.room:''].filter(Boolean).map(esc).join(' · ')}</small></span>${ed?`<span class="sc-b"><button type="button" class="ib" data-sche="${x.id}" aria-label="Изменить пару" title="Изменить">${I.edit||'✎'}</button><button type="button" class="ib" data-schx="${x.id}" aria-label="Удалить пару" title="Удалить">${I.x}</button></span>`:''}</li>`};
const schedList=(a,ed,live)=>{let h='',prev=null;for(const x of a){if(prev){const g=tMin(x.time)-tMin(schedEnd(prev));if(g>=30)h+=`<li class="sc-gap">окно ${durTxt(g)}</li>`}h+=schedRow(x,ed,live);prev=x}return `<ul class="sc-l">${h}</ul>`};
const schedWd=()=>{const wd=new Date().getDay();return wd>=1&&wd<=6?wd:0};
function homeSched(){const wd=new Date().getDay(),today=schedWd(),ta=today?schedDay(today):[],left=ta.filter(x=>tMin(schedEnd(x))>schedNowMin()),useToday=left.length>0,show=useToday?today:(wd>=6||wd===0?1:wd+1),a=useToday?ta:schedDay(show);
 if(!S.sched.length)return `<section class="card pad hp-sc"><div class="pg-h"><h2>Моё расписание</h2></div><p class="muted">Заполни расписание один раз, и здесь будут пары на сегодня и завтра.</p><a class="btn btn-o btn-sm" href="/account?tab=sched">Заполнить расписание</a></section>`;
 return `<section class="card pad hp-sc"><div class="pg-h"><h2>${useToday?'Сегодня':show===wd+1?'Завтра':WD_S[show]}<span class="small muted" style="font-weight:400"> · ${a.length?(useToday?'пары до ':'')+(useToday?a.map(schedEnd).sort().pop():schedSpan(a)):WD_S[show].toLowerCase()}</span></h2><a class="link" href="/account?tab=sched">Вся неделя</a></div>${a.length?schedList(a,false,useToday):'<p class="muted">Пар нет.</p>'}</section>`}
let SCH_ED=null;
function schedHtml(){const ed=SCH_ED&&S.sched.find(x=>x.id===SCH_ED),today=schedWd(),ta=today?schedDay(today):[],slots=[...new Set(S.sched.map(x=>x.time+'–'+schedEnd(x)))].sort().slice(0,8),tot=S.sched.length;
 const sum=!tot?'':today&&ta.length?`Сегодня ${schedSpan(ta).replace(' · ',', с ').replace('–',' до ')}.`:'Сегодня пар нет.';
 return `<section class="card pad"><div class="pg-h"><h2>${ed?'Изменить пару':'Добавить пару'}</h2>${tot?`<span class="small muted">${sum} На неделе ${plural(tot,'пара','пары','пар')}.</span>`:''}</div><form class="sc-f" id="scF" novalidate>${ed?`<input type="hidden" name="eid" value="${ed.id}">`:''}<label class="fl">День<select class="f" name="day">${WD_S.slice(1).map((d,i)=>`<option value="${i+1}" ${(ed?ed.day:today||1)===i+1?'selected':''}>${d}</option>`).join('')}</select></label><label class="fl">Начало<input type="time" name="time" value="${ed?esc(ed.time):'09:00'}"></label><label class="fl">Конец<input type="time" name="end" value="${ed?esc(schedEnd(ed)):'10:30'}"></label><label class="fl sc-w">Предмет<span class="dm-cb sc-cb"><input type="text" name="title" maxlength="100" placeholder="Начни вводить название" value="${ed?esc(ed.title):''}" data-scsubj autocomplete="off" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="scSug"><span class="dm-sug sc-sug" id="scSug" role="listbox" hidden></span></span></label><label class="fl">Тип<select class="f" name="kind">${['Лекция','Семинар','Практика',''].map(k=>`<option ${ed&&ed.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="fl">Аудитория<input type="text" name="room" maxlength="20" placeholder="313" value="${ed?esc(ed.room||''):''}"></label><button class="btn btn-o btn-sm">${ed?'Сохранить':'Добавить'}</button>${ed?'<button type="button" class="btn btn-oo btn-sm" data-schc>Отмена</button>':''}</form>${slots.length?`<div class="sc-sl"><span class="small muted">Время как у других пар:</span>${slots.map(x=>`<button type="button" class="tab" data-schs="${x}">${x}</button>`).join('')}</div>`:'<p class="small muted sc-h">Конец подставляется сам: начало плюс полтора часа. Если пара другой длины, поправь.</p>'}</section>
 ${tot?`<div class="sc-week">${[1,2,3,4,5,6].map(d=>{const a=schedDay(d);return a.length?`<section class="card pad ${d===today?'today':''}"><div class="sc-dh"><h3>${WD_S[d]}${d===today?' <span class="tag soon">сегодня</span>':''}</h3><span class="small muted">${schedSpan(a)}</span></div>${schedList(a,true,d===today)}</section>`:''}).join('')}</div>`:'<div class="card pad empty"><p class="muted">Расписание пустое. Добавь пары по одной: день и время следующей подставятся сами.</p></div>'}`}
const _RAccS=R.account;R.account=p=>{p=p||{};if(!S.auth||p.tab!=='sched')return _RAccS(p);return{title:`Расписание: ${D.brand}`,html:`<div class="wrap cb">${cabNav('sched','')}<div class="phead cb-h"><div><h1 tabindex="-1">Расписание</h1><p class="d">Твои пары по дням с началом и концом. Видишь только ты.</p></div></div><div id="scBox" class="stack">${schedHtml()}</div></div>`,after:cabCounts}};
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='scF')return;e.preventDefault();const title=f.title.value.trim();if(!title){toast('Напиши предмет');f.title.focus();return}if(!f.time.value){toast('Укажи время начала');return}if(!f.end.value||tMin(f.end.value)<=tMin(f.time.value)){toast('Конец пары должен быть позже начала');f.end.focus();return}
 const rec={day:+f.day.value,time:f.time.value,end:f.end.value,title,kind:f.kind.value,room:f.room.value.trim()},eid=f.elements.eid?f.elements.eid.value:'';
 if(eid){const x=S.sched.find(k=>k.id===eid);if(x)Object.assign(x,rec);SCH_ED=null;store.set('sched',S.sched);$('#scBox').innerHTML=schedHtml();toast('Пара изменена');return}
 if(S.sched.length>=80){toast('Слишком много пар');return}S.sched.push({id:wUid(),...rec});store.set('sched',S.sched);$('#scBox').innerHTML=schedHtml();const n=$('#scF'),st=Math.min(tMin(rec.end)+15,1320);n.day.value=rec.day;n.time.value=tStr(st);n.end.value=tStr(st+tMin(rec.end)-tMin(rec.time));n.kind.value=rec.kind;n.title.focus();toast('Пара добавлена')});
document.addEventListener('change',e=>{const i=e.target;if(i.name!=='time'||!i.form||i.form.id!=='scF'||!i.value)return;const f=i.form,len=f.dataset.len?+f.dataset.len:90;f.end.value=tStr(tMin(i.value)+len)});
document.addEventListener('input',e=>{const i=e.target;if(i.name!=='end'||!i.form||i.form.id!=='scF'||!i.value||!i.form.time.value)return;const l=tMin(i.value)-tMin(i.form.time.value);if(l>0)i.form.dataset.len=l});
document.addEventListener('click',e=>{let b;if(b=e.target.closest('[data-sche]')){SCH_ED=b.dataset.sche;$('#scBox').innerHTML=schedHtml();const f=$('#scF');f.scrollIntoView({block:'center',behavior:noMotion?'auto':'smooth'});f.title.focus();return}
 if(e.target.closest('[data-schc]')){SCH_ED=null;$('#scBox').innerHTML=schedHtml();return}
 if(b=e.target.closest('[data-schs]')){const [a,z]=b.dataset.schs.split('–'),f=$('#scF');f.time.value=a;f.end.value=z;f.dataset.len=tMin(z)-tMin(a);f.title.focus()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-schx]');if(!b)return;S.sched=S.sched.filter(x=>x.id!==b.dataset.schx);if(SCH_ED===b.dataset.schx)SCH_ED=null;store.set('sched',S.sched);$('#scBox').innerHTML=schedHtml()});
/* Степан иногда напоминает про правки */
const steNudge=()=>S.admin||Math.random()>0.4?'':`<a class="card pad hp-ste" href="/contrib">${spr('ste_coin','')}<span><b>Актуализируй и заработай</b><small class="muted">Поправь конспект или разбалловку своего предмета. За принятую правку Степан начисляет рубли.</small></span></a>`;

/* ===================== личные сообщения: запрос → согласие → переписка ===================== */
const DM={list:[],cur:null,unread:0};
const dmOk=()=>API_ON&&!!apiTok()&&window.API_H&&API_H.wiki>=9;
const dmTag=t=>t.status==='pending'?(t.mine?'<span class="tag">ждёт ответа</span>':'<span class="tag soon">запрос тебе</span>'):t.status==='no'?'<span class="tag bad">закрыт</span>':t.unread?`<span class="cn-c">${t.unread}</span>`:'';
const dmListHtml=()=>DM.list.length?DM.list.map(t=>`<a class="dm-t ${DM.cur&&DM.cur.id===t.id?'on':''}" href="/chats?t=${t.id}"><b>${esc(t.with)}</b>${dmTag(t)}<small class="muted">${t.last?esc((t.last.by===wWho()?'Ты: ':'')+t.last.text):''}</small></a>`).join(''):'<p class="muted small" style="padding:12px">Переписок пока нет.</p>';
const dmMsgs=t=>{const me=wWho();let day='';return t.msgs.map(m=>{const d=fmtD(iso(new Date(m.at))),sep=d!==day?`<div class="ws-day">${d}</div>`:'';day=d;const x=new Date(m.at);return `${sep}<div class="ws-m ${m.by===me?'me':''}"><div class="ws-mb"><p>${esc(m.text).replace(/(https:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>').replace(/\n/g,'<br>')}</p><small>${z2(x.getHours())}:${z2(x.getMinutes())}</small></div></div>`}).join('')};
function dmThreadHtml(){const t=DM.cur;if(!t)return `<div class="dm-e"><p class="muted">Выбери переписку слева или начни новую.</p><form id="dmNew" class="dm-new" novalidate><h2>Новая переписка</h2><div class="dm-cb"><label class="fl" for="dmTo">Кому</label><input type="text" id="dmTo" name="login" maxlength="40" placeholder="Начни вводить логин" autocomplete="off" role="combobox" aria-expanded="false" aria-controls="dmSug" aria-autocomplete="list"><div class="dm-sug" id="dmSug" role="listbox" hidden></div></div><label class="fl">Первое сообщение<textarea name="text" rows="3" maxlength="2000" placeholder="Человек увидит его вместе с запросом и решит, отвечать ли"></textarea></label><button class="btn btn-o btn-sm">Отправить запрос</button><p class="small muted">Писать дальше можно только после того, как человек примет запрос.</p></form></div>`;
 const foot=t.status==='ok'?`<form class="ws-chf" id="dmF"><textarea id="dmMsg" rows="1" maxlength="2000" placeholder="Сообщение. Enter — отправить" aria-label="Сообщение"></textarea><button class="btn btn-o btn-sm">Отправить</button></form>`:t.status==='pending'?(t.mine?'<p class="dm-st muted">Запрос отправлен. Писать дальше можно, когда его примут.</p>':`<div class="dm-st"><span>${esc(t.with)} хочет переписываться с тобой.</span><button type="button" class="btn btn-o btn-sm" data-dmop="accept">Принять</button><button type="button" class="btn btn-oo btn-sm" data-dmop="decline">Отклонить</button></div>`):'<p class="dm-st muted">Переписка закрыта.</p>';
 return `<div class="dm-h"><a class="link dm-back" href="/chats">← Все</a><b>${esc(t.with)}</b>${t.status==='ok'?'<button type="button" class="link wk-del" data-dmop="decline">Закрыть переписку</button>':''}</div><div class="ws-chl" id="dmL">${dmMsgs(t)}</div>${foot}`}
function dmDraw(){const a=$('#dmList'),b=$('#dmThread');if(!a)return;const draft=$('#dmMsg')?$('#dmMsg').value:'',foc=document.activeElement&&document.activeElement.id==='dmMsg';a.innerHTML=dmListHtml();b.innerHTML=dmThreadHtml();$('.dm').classList.toggle('open',!!DM.cur);const l=$('#dmL');if(l)l.scrollTop=l.scrollHeight;const i=$('#dmMsg');if(i){i.value=draft;if(foc||DM.cur)i.focus()}}
async function dmLoad(id){await API_READY;if(!dmOk()){const b=$('#dmThread');if(b)b.innerHTML='<div class="dm-e"><p>Сообщения хранятся на сервере, а он сейчас не отвечает. Попробуй позже.</p></div>';return}try{const [l,t]=await Promise.all([api('/api/dm'),id?api('/api/dm/'+id).catch(()=>null):null]);DM.list=l.threads;DM.cur=t?t.thread:null;if(DM.cur){const x=DM.list.find(k=>k.id===DM.cur.id);if(x)x.unread=0}dmBadge();dmDraw()}catch(x){toast(x.message)}}
function dmBadge(){DM.unread=DM.list.reduce((a,t)=>a+(t.status==='pending'?(t.mine?0:1):t.status==='ok'?(t.unread||0):0),0);$$('[data-dmn]').forEach(e=>e.textContent=DM.unread||'');const c=$('#hdr .cab-b');if(c)c.classList.toggle('has-dm',DM.unread>0)}
R.chats=p=>{if(!S.auth)return R.login({});return{title:`Сообщения: ${D.brand}`,html:`<div class="wrap cb">${cabNav('chats','')}<div class="phead cb-h"><div><h1 tabindex="-1">Сообщения</h1><p class="d">Личная переписка со студентами. Сначала запрос, переписка — после согласия.</p></div><a class="btn btn-o btn-sm" href="/chats">+ Новая переписка</a></div><div class="card dm"><aside id="dmList" class="dm-l">${dmListHtml()}</aside><section id="dmThread" class="dm-r"><div class="dm-e"><p class="muted">Загружаю…</p></div></section></div></div>`,after:()=>{DM.cur=null;dmLoad((p||{}).t);cabCounts()}}};
document.addEventListener('submit',async e=>{const f=e.target;
 if(f.id==='dmNew'){e.preventDefault();const login=f.login.value.trim(),text=f.text.value.trim();if(!login){toast('Напиши, кому');f.login.focus();return}if(!text){toast('Напиши первое сообщение');f.text.focus();return}try{const r=await api('/api/dm',{login,text});toast('Запрос отправлен');LOC.hash='/chats?t='+r.id}catch(x){toast(x.message)}}
 if(f.id==='dmF'){e.preventDefault();const i=$('#dmMsg'),t=i.value.trim();if(!t)return;i.value='';try{DM.cur=(await api('/api/dm/'+DM.cur.id,{op:'msg',text:t})).thread;const l=$('#dmL');l.innerHTML=dmMsgs(DM.cur);l.scrollTop=l.scrollHeight}catch(x){toast(x.message);i.value=t}}});
/* выпадающий список студентов в поле «Кому» */
const DMS={t:0,q:null,list:[],i:-1};
const dmSugClose=()=>{const b=$('#dmSug'),i=$('#dmTo');if(b)b.hidden=true;if(i)i.setAttribute('aria-expanded','false');DMS.i=-1};
const dmSugDraw=()=>{const b=$('#dmSug'),i=$('#dmTo');if(!b||!i)return;b.innerHTML=DMS.list.length?DMS.list.map((u,k)=>`<button type="button" role="option" class="dm-o ${k===DMS.i?'on':''}" data-dmpick="${esc(u.login)}" aria-selected="${k===DMS.i}"><b>${esc(u.login)}</b>${u.badge?`<span class="ach sm">${esc(u.badge)}</span>`:''}${u.near?'<small class="muted">из твоей команды</small>':''}</button>`).join('')+(DMS.total>DMS.list.length?`<p class="small muted dm-more">Показаны первые ${DMS.list.length} из ${DMS.total}. Начни вводить логин, чтобы сузить.</p>`:''):`<p class="small muted dm-more">${i.value.trim()?'Никого не нашлось. Проверь логин или впиши @ник в Telegram целиком.':'На сайте пока нет других студентов.'}</p>`;b.hidden=false;i.setAttribute('aria-expanded','true')};
async function dmSug(now){const i=$('#dmTo');if(!i||!dmOk()||!(API_H.wiki>=10))return;clearTimeout(DMS.t);DMS.t=setTimeout(async()=>{const q=i.value.trim();if(!q){dmSugClose();return}try{const r=await api('/api/people?q='+encodeURIComponent(q));if($('#dmTo')!==i||i.value.trim()!==q)return;DMS.list=r.people;DMS.total=r.total;DMS.i=-1;dmSugDraw()}catch{}},now?0:160)}
document.addEventListener('focusin',e=>{if(e.target.id==='dmTo')dmSug(true)});
document.addEventListener('input',e=>{if(e.target.id==='dmTo')dmSug()});
document.addEventListener('focusout',e=>{if(e.target.id==='dmTo')setTimeout(()=>{if(document.activeElement&&document.activeElement.id==='dmTo')return;dmSugClose()},180)});
document.addEventListener('keydown',e=>{if(e.target.id!=='dmTo')return;const b=$('#dmSug');if(e.key==='Escape'){dmSugClose();return}if(!b||b.hidden||!DMS.list.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();DMS.i=(DMS.i+(e.key==='ArrowDown'?1:-1)+DMS.list.length)%DMS.list.length;dmSugDraw();const o=$('.dm-o.on');o&&o.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&DMS.i>=0){e.preventDefault();e.target.value=DMS.list[DMS.i].login;dmSugClose();const t=$('#dmNew [name=text]');t&&t.focus()}});
document.addEventListener('mousedown',e=>{const o=e.target.closest('[data-dmpick]');if(o){e.preventDefault();const i=$('#dmTo');i.value=o.dataset.dmpick;dmSugClose();const t=$('#dmNew [name=text]');t&&t.focus();return}if(e.target.closest('[data-dmdd]')){e.preventDefault();const i=$('#dmTo'),b=$('#dmSug');if(b&&!b.hidden){dmSugClose();return}if(document.activeElement===i)dmSug(true);else i.focus()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-dmop]');if(!b||!DM.cur)return;const op=b.dataset.dmop;if(op==='decline'&&DM.cur.status==='ok'&&!confirm('Закрыть переписку? Писать друг другу больше не получится.'))return;try{await api('/api/dm/'+DM.cur.id,{op});if(op==='decline'){LOC.hash='/chats';dmLoad()}else dmLoad(DM.cur.id)}catch(x){toast(x.message)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='dmMsg'){e.preventDefault();$('#dmF').requestSubmit()}});
/* новые сообщения: открытый чат раз в 5 секунд, счётчик непрочитанных раз в 40 секунд */
setInterval(async()=>{if(document.hidden||!$('#dmThread')||!DM.cur||!dmOk())return;try{const t=(await api('/api/dm/'+DM.cur.id)).thread;if(!DM.cur||t.id!==DM.cur.id)return;const prev=DM.cur.status,ch=t.msgs.length!==DM.cur.msgs.length||t.status!==prev;DM.cur=t;if(ch){if(t.status!==prev)dmDraw();else{const l=$('#dmL'),bt=l.scrollHeight-l.scrollTop-l.clientHeight<60;l.innerHTML=dmMsgs(t);if(bt)l.scrollTop=l.scrollHeight}}}catch{}},5000);
async function dmPoll(){if(document.hidden||!S.auth)return;await API_READY;if(!dmOk())return;try{DM.list=(await api('/api/dm')).threads;const was=DM.unread;dmBadge();if($('#dmList')&&!DM.cur)$('#dmList').innerHTML=dmListHtml();if(DM.unread>was&&!$('#dmThread'))toast('Новое личное сообщение')}catch{}}
setInterval(dmPoll,40000);setTimeout(dmPoll,3000);

