const NOTE_MAX=900;
function notePreview(html){const box=document.createElement('div');box.innerHTML=html;let len=0,imgs=0,cut=false;const keep=[];let root=box,wrap=[];
 while(root.children.length===1&&root.childNodes.length<=3&&root.firstElementChild.children.length>1){wrap.push(root.firstElementChild.cloneNode(false));root=root.firstElementChild}
 for(const n of [...root.childNodes]){const t=(n.textContent||'').length,im=n.querySelectorAll?n.querySelectorAll('img').length+(n.nodeName==='IMG'?1:0):0;
  if(keep.length&&(len+t>NOTE_MAX||imgs+im>1)){cut=true;break}keep.push(n);len+=t;imgs+=im}
 if(!cut)return null;const o=document.createElement('div');let tgt=o;wrap.forEach(w=>{tgt.appendChild(w);tgt=w});keep.forEach(n=>tgt.appendChild(n.cloneNode(true)));return{html:o.innerHTML,rest:Math.max(0,(box.textContent||'').length-len),imgs:box.querySelectorAll('img').length}}
