/* подсказки логинов при наборе (добавление в проект и другие поля с data-people) */
const PPL={t:0,i:-1,list:[]};
const ppBox=i=>i.parentElement.querySelector('.pp-sug');
const ppClose=i=>{const b=ppBox(i);if(b)b.hidden=true;i.setAttribute('aria-expanded','false');PPL.i=-1};
const ppDraw=i=>{const b=ppBox(i);if(!b)return;b.innerHTML=PPL.list.length?PPL.list.map((u,k)=>`<button type="button" role="option" class="dm-o ${k===PPL.i?'on':''}" data-pppick="${esc(u.login)}" aria-selected="${k===PPL.i}"><b>${esc(u.login)}</b>${u.badge?`<span class="ach sm">${esc(u.badge)}</span>`:''}${u.near?'<small class="muted">уже знакомы</small>':''}</button>`).join(''):`<p class="small muted dm-more">${i.value.trim()?'Никого не нашлось. Человек должен быть зарегистрирован на сайте.':'Пока некого добавить.'}</p>`;b.hidden=false;i.setAttribute('aria-expanded','true')};
function ppSug(i,now){if(WS&&WS.demo||!(API_H&&API_H.wiki>=10)||!wWho())return;clearTimeout(PPL.t);PPL.t=setTimeout(async()=>{const q=i.value.trim();if(!q){ppClose(i);return}try{const r=await api('/api/people?q='+encodeURIComponent(q));if(i.value.trim()!==q)return;const ex=new Set((i.dataset.people||'').split(',').map(x=>x.toLowerCase()));PPL.list=r.people.filter(u=>!ex.has(u.login.toLowerCase())).slice(0,8);PPL.i=-1;ppDraw(i)}catch{}},now?0:150)}
document.addEventListener('focusin',e=>{if(e.target.matches&&e.target.matches('[data-people]'))ppSug(e.target,true)});
document.addEventListener('input',e=>{if(e.target.matches&&e.target.matches('[data-people]'))ppSug(e.target)});
document.addEventListener('focusout',e=>{const i=e.target;if(i.matches&&i.matches('[data-people]'))setTimeout(()=>{if(document.activeElement!==i)ppClose(i)},180)});
document.addEventListener('keydown',e=>{const i=e.target;if(!(i.matches&&i.matches('[data-people]')))return;const b=ppBox(i);if(e.key==='Escape'){ppClose(i);return}if(!b||b.hidden||!PPL.list.length)return;
 if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();PPL.i=(PPL.i+(e.key==='ArrowDown'?1:-1)+PPL.list.length)%PPL.list.length;ppDraw(i)}else if(e.key==='Enter'&&PPL.i>=0){e.preventDefault();i.value=PPL.list[PPL.i].login;ppClose(i)}});
