{const _cl=e=>{const b=e.target.closest('[data-wsmatx]');if(!b)return;const m=WS.p&&WS.p.mats.find(x=>x.id===b.dataset.wsmatx);if(m&&!confirm(`Убрать «${m.name}» из материалов?`)){e.stopImmediatePropagation();e.preventDefault()}};document.addEventListener('click',_cl,true)}

